INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.CREATI.MY_PURPOSE_TALENTS_AND_A.TALENTS_PARABLE', 'CRE.G5.CREATI.MY_PURPOSE_TALENTS_AND_A', 'cre', 5, 'Know the parable of the talents (Matthew 25:14-30) and what it teaches', ARRAY['CRE.G5.CREATI.MY_PURPOSE_TALENTS_AND_A.b', 'CRE.G5.CREATI.MY_PURPOSE_TALENTS_AND_A.c']::text[], 'Says that the master gave five, two and one talents, each according to ability; that the first two servants used theirs and gained more; that the third buried his; that the master praised the faithful servants; and that the lesson is to use what God has given. Does not read the talents as only money or say the master was unfair. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the parable","what each servant did","which lesson fits a situation","say why the third servant was blamed"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.CREATI.MY_PURPOSE_TALENTS_AND_A.PURPOSE_VERSES', 'CRE.G5.CREATI.MY_PURPOSE_TALENTS_AND_A', 'cre', 5, 'Know what Jeremiah 29:11, James 1:17 and 1 Peter 4:10 say about God''s purpose and gifts', ARRAY['CRE.G5.CREATI.MY_PURPOSE_TALENTS_AND_A.a']::text[], 'Says that God has plans for the child''s welfare, future and hope (Jeremiah 29:11), that every good gift comes from God (James 1:17) and that each person should use the gift received to serve others (1 Peter 4:10). Does not say that gifts are for showing off or only for adults. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["match a verse to its message","what a gift is for","choose the response that fits the verse"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.CREATI.WORK.STEWARDSHIP', 'CRE.G5.CREATI.WORK', 'cre', 5, 'Know the work God gave human beings and the roles at home, school and church', ARRAY['CRE.G5.CREATI.WORK.a', 'CRE.G5.CREATI.WORK.c']::text[], 'Names the responsibilities in Genesis 1:26 and 2:15 (rule over, look after, till and keep the garden) and tells caring for creation from using it up. Gives roles a child really has at home, at school and at church. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which verse gives which work","what looking after creation means","a role at home, school or church"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.CREATI.WORK.CHILD_LABOUR', 'CRE.G5.CREATI.WORK', 'cre', 5, 'Tell child labour from age-appropriate chores, with its causes, effects and where to report', ARRAY['CRE.G5.CREATI.WORK.d', 'CRE.G5.CREATI.WORK.e']::text[], 'Separates child labour (work that is heavy, harmful, or keeps a child from school) from light chores that suit a child''s age; gives causes (poverty, ignorance, greed of employers, loss of parents) and effects (missing school, harm to health, loss of play and safety); and names safe people to report to (a parent or guardian, a teacher, the chief, a children''s officer or the Childline Kenya helpline 116). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chore or child labour","a cause of child labour","an effect of child labour","who to tell"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.CREATI.THE_FALL_OF_MAN.FALL_OF_MAN', 'CRE.G5.CREATI.THE_FALL_OF_MAN', 'cre', 5, 'Know the story of the fall of man (Genesis 3:1-11) and its lessons', ARRAY['CRE.G5.CREATI.THE_FALL_OF_MAN.a', 'CRE.G5.CREATI.THE_FALL_OF_MAN.b']::text[], 'Says that the serpent tempted the woman, that she and the man ate from the tree God had forbidden, that they hid when they heard God, and that God asked "Where are you?"; and states lessons: obey God, do not blame others, wrong choices have results. Does not say the Bible names the fruit. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the story","put events in order","a lesson from the story","what the serpent did"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.CREATI.FAMILY_UNITY.FAMILY_UNITY', 'CRE.G5.CREATI.FAMILY_UNITY', 'cre', 5, 'Know why family unity matters, its challenges and how a child helps (Colossians 3:13-14)', ARRAY['CRE.G5.CREATI.FAMILY_UNITY.a', 'CRE.G5.CREATI.FAMILY_UNITY.b', 'CRE.G5.CREATI.FAMILY_UNITY.c']::text[], 'Gives reasons family unity matters (love, help, peace, safety), names challenges families face (quarrels, poverty, illness, long absence, unkind words), and gives ways a child helps (forgiving, doing chores, speaking kindly, obeying). Knows that Colossians 3:13-14 speaks of bearing with one another, forgiving and love. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["why unity matters","a challenge families face","what a child can do","what Colossians 3:13-14 says"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.THE_BI.THE_BIBLE_AS_A_GUIDE.BIBLE_GUIDE', 'CRE.G5.THE_BI.THE_BIBLE_AS_A_GUIDE', 'cre', 5, 'Know how the Bible guides and why Christians read it (Joshua 1:8, Psalm 1:1-3)', ARRAY['CRE.G5.THE_BI.THE_BIBLE_AS_A_GUIDE.a', 'CRE.G5.THE_BI.THE_BIBLE_AS_A_GUIDE.b']::text[], 'Gives uses of the Bible in society (teaching right and wrong, comfort, guidance, worship, prayer, oaths on some occasions, moral teaching in schools) and benefits of reading it (growing in faith, wisdom, strength, direction). Knows that Joshua 1:8 and Psalm 1:1-3 speak of meditating on God''s word and its blessing. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["a use of the Bible","a benefit of reading it","what Joshua 1:8 or Psalm 1:1-3 says"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.THE_BI.BIBLE_STORIES_PETER_AND_.PETER_JOHN', 'CRE.G5.THE_BI.BIBLE_STORIES_PETER_AND_', 'cre', 5, 'Know the story of Peter and John before the rulers (Acts 4) and why Christians stand firm', ARRAY['CRE.G5.THE_BI.BIBLE_STORIES_PETER_AND_.a', 'CRE.G5.THE_BI.BIBLE_STORIES_PETER_AND_.b', 'CRE.G5.THE_BI.BIBLE_STORIES_PETER_AND_.c']::text[], 'Says that Peter and John were arrested for teaching about Jesus, were questioned about the power by which a man had been healed, that Peter, filled with the Holy Spirit, spoke boldly, that he said there is salvation in no other name than Jesus (Acts 4:12), and that the rulers saw their courage and knew they had been with Jesus. Gives a reason to stand firm. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the story","what Peter said","a lesson from the story","why stand firm"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.THE_BI.KING_SOLOMON_THE_WISE_RU.SOLOMON', 'CRE.G5.THE_BI.KING_SOLOMON_THE_WISE_RU', 'cre', 5, 'Know the story of Solomon and the two women (1 Kings 3:16-28) and what it teaches', ARRAY['CRE.G5.THE_BI.KING_SOLOMON_THE_WISE_RU.a', 'CRE.G5.THE_BI.KING_SOLOMON_THE_WISE_RU.b', 'CRE.G5.THE_BI.KING_SOLOMON_THE_WISE_RU.c']::text[], 'Says that two women claimed one living baby, that Solomon called for a sword to divide the child, that the real mother gave up her claim to save the child, and that Solomon gave the baby to her. Gives lessons (wisdom, listening to both sides, love shows in giving) and what Proverbs 9:10 says. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the story","how Solomon found the mother","a lesson or a wise choice","what Proverbs 9:10 says"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.THE_BI.NOAH_AND_HIS_SONS.NOAH_SONS', 'CRE.G5.THE_BI.NOAH_AND_HIS_SONS', 'cre', 5, 'Know the story of Noah and his sons (Genesis 9:18-23)', ARRAY['CRE.G5.THE_BI.NOAH_AND_HIS_SONS.a']::text[], 'Names Shem, Ham and Japheth as the sons of Noah who came out of the ark; says that Noah planted a vineyard, drank wine and lay uncovered in his tent; that Ham told his brothers; and that Shem and Japheth covered their father without looking. Does not mix up the sons with other Bible brothers. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["name the sons","what each son did","a fact of the story"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.THE_BI.NOAH_AND_HIS_SONS.RESPECT_ELDERLY', 'CRE.G5.THE_BI.NOAH_AND_HIS_SONS', 'cre', 5, 'Know ways of showing respect to the elderly', ARRAY['CRE.G5.THE_BI.NOAH_AND_HIS_SONS.b']::text[], 'Gives ways of showing respect to older people (greeting politely, listening, helping with loads and chores, giving a seat, speaking kindly, visiting) and does not think respect means agreeing with everything or only applies to relatives. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which action shows respect","what to do in a situation","why respect the elderly"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.THE_BI.A_HAND_WRITES_ON_THE_WAL.WRITING_ON_WALL', 'CRE.G5.THE_BI.A_HAND_WRITES_ON_THE_WAL', 'cre', 5, 'Know the story of the hand that wrote on the wall (Daniel 5)', ARRAY['CRE.G5.THE_BI.A_HAND_WRITES_ON_THE_WAL.a', 'CRE.G5.THE_BI.A_HAND_WRITES_ON_THE_WAL.b']::text[], 'Says that King Belshazzar held a feast and used the gold and silver vessels from the temple in Jerusalem, that a human hand wrote on the wall, that no wise man could read it, that Daniel was called and read it, and that the writing said the kingdom had been counted, weighed and divided. Gives lessons (do not misuse holy things, pride has a price, God is above kings). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the story","what the writing meant","who did what","a lesson from the story"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.THE_BI.A_HAND_WRITES_ON_THE_WAL.HUMILITY_DANIEL', 'CRE.G5.THE_BI.A_HAND_WRITES_ON_THE_WAL', 'cre', 5, 'Know what humility is and how Daniel showed it', ARRAY['CRE.G5.THE_BI.A_HAND_WRITES_ON_THE_WAL.c']::text[], 'Describes humility as thinking rightly of yourself and others, without boasting; gives benefits (peace, learning, friends, honour from God and people) and tells Daniel''s quiet, faithful service from the proud king''s behaviour. Does not say that humility means being weak or having no opinion. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the humble action","a benefit of humility","Daniel or the proud king"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.THE_BI.MOUNT_CARMEL_CONTEST.CARMEL', 'CRE.G5.THE_BI.MOUNT_CARMEL_CONTEST', 'cre', 5, 'Know the contest on Mount Carmel (1 Kings 18:22-39) and what it teaches', ARRAY['CRE.G5.THE_BI.MOUNT_CARMEL_CONTEST.a', 'CRE.G5.THE_BI.MOUNT_CARMEL_CONTEST.c']::text[], 'Says that Elijah stood alone against 450 prophets of Baal, that each side prepared a bull and no one lit the fire, that Baal did not answer, that Elijah prayed and the fire of the Lord fell, and that the people said the Lord is God. Gives lessons (worship God alone, trust in prayer, courage to stand alone). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the contest","what each side did","what the people said","a lesson from the contest"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.THE_BI.MOUNT_CARMEL_CONTEST.TRUE_GOD', 'CRE.G5.THE_BI.MOUNT_CARMEL_CONTEST', 'cre', 5, 'Tell the true God from false gods and know why worship belongs to God alone', ARRAY['CRE.G5.THE_BI.MOUNT_CARMEL_CONTEST.b']::text[], 'Tells the Lord who answered by fire from idols that cannot hear, see or speak; knows that the Ten Commandments forbid worshipping other gods and making idols to bow down to; and chooses a safe response when a group or friend invites a child to worship or follow something against these teachings. Never judges other people by name. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what can an idol do","which commandment idea fits","what to do when invited to a harmful group"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.THE_BI.THE_BIRTH_OF_MOSES.MOSES_BIRTH', 'CRE.G5.THE_BI.THE_BIRTH_OF_MOSES', 'cre', 5, 'Know the story of the birth of Moses (Exodus 2:1-10) and what it teaches', ARRAY['CRE.G5.THE_BI.THE_BIRTH_OF_MOSES.a', 'CRE.G5.THE_BI.THE_BIRTH_OF_MOSES.b']::text[], 'Says that Moses'' mother hid him for three months, put him in a basket among the reeds of the Nile, that his sister watched, that Pharaoh''s daughter found him and took pity, that his own mother was paid to nurse him, and that he was named Moses. Gives lessons (God protects, courage of a mother, kindness to a stranger). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the story","what happened in order","who helped Moses","a lesson from the story"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.THE_BI.THE_CALL_OF_MOSES.MOSES_CALL', 'CRE.G5.THE_BI.THE_CALL_OF_MOSES', 'cre', 5, 'Know the call of Moses (Exodus 3:1-10) and how Christian leaders obey God', ARRAY['CRE.G5.THE_BI.THE_CALL_OF_MOSES.a', 'CRE.G5.THE_BI.THE_CALL_OF_MOSES.b', 'CRE.G5.THE_BI.THE_CALL_OF_MOSES.c']::text[], 'Says that Moses was looking after the flock when he saw a bush that burned without burning up, that God told him to take off his sandals because the ground was holy, that God had seen the people''s suffering, and that Moses was sent to bring them out of Egypt. Gives lessons and ways Christian leaders obey God today. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the call","what God said to Moses","a lesson from the call","how a leader obeys God today"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.THE_LI.JOHN_THE_BAPTIST.JOHN_BAPTIST', 'CRE.G5.THE_LI.JOHN_THE_BAPTIST', 'cre', 5, 'Know the teaching of John the Baptist (Luke 3:3-14) and its lessons', ARRAY['CRE.G5.THE_LI.JOHN_THE_BAPTIST.a', 'CRE.G5.THE_LI.JOHN_THE_BAPTIST.b']::text[], 'Says that John preached repentance and baptism, that he told the crowd to share spare clothing and food, told tax collectors to collect no more than was due, and told soldiers not to take money by force or accuse falsely and to be content with their pay. Gives lessons (repent, share, be honest, be content). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what John told each group","what repentance means","a lesson from John''s teaching"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.THE_LI.THE_BAPTISM_OF_JESUS_CHR.BAPTISM_JESUS', 'CRE.G5.THE_LI.THE_BAPTISM_OF_JESUS_CHR', 'cre', 5, 'Know the events at the baptism of Jesus (Luke 3:21-22) and why baptism matters', ARRAY['CRE.G5.THE_LI.THE_BAPTISM_OF_JESUS_CHR.a', 'CRE.G5.THE_LI.THE_BAPTISM_OF_JESUS_CHR.b']::text[], 'Says that Jesus was baptised and was praying, that heaven opened, that the Holy Spirit came down like a dove, and that a voice from heaven called him the beloved Son. Gives the meaning Christians agree on (a sign of repentance, new life and belonging to God) without saying how or at what age baptism should be done. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall an event at the baptism","what the voice said","what baptism shows"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.THE_LI.CALMING_THE_STORM.CALMING_STORM', 'CRE.G5.THE_LI.CALMING_THE_STORM', 'cre', 5, 'Know the miracle of calming the storm (Mark 4:35-39) and what it teaches', ARRAY['CRE.G5.THE_LI.CALMING_THE_STORM.a', 'CRE.G5.THE_LI.CALMING_THE_STORM.b', 'CRE.G5.THE_LI.CALMING_THE_STORM.c']::text[], 'Says that a great storm came while Jesus slept in the boat, that the disciples woke him and asked if he did not care, that Jesus told the wind and waves to be still and there was a great calm. Gives lessons (Jesus has power over nature, trust in God in trouble) and challenges Christians face. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the miracle","what Jesus said and did","a lesson from the miracle","what to do in a challenge"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.THE_LI.FEEDING_THE_FOUR_THOUSAN.FEEDING_4000', 'CRE.G5.THE_LI.FEEDING_THE_FOUR_THOUSAN', 'cre', 5, 'Know the feeding of the four thousand (Matthew 15:32-38) and ways of helping the needy', ARRAY['CRE.G5.THE_LI.FEEDING_THE_FOUR_THOUSAN.a', 'CRE.G5.THE_LI.FEEDING_THE_FOUR_THOUSAN.b', 'CRE.G5.THE_LI.FEEDING_THE_FOUR_THOUSAN.c']::text[], 'Says that the crowd had been with Jesus three days, that Jesus had compassion, that there were seven loaves and a few small fish, that all ate and seven baskets were left, and does not mix it with the feeding of five thousand. Gives four ways of helping needy people today. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the miracle","four thousand or five thousand","a lesson from the miracle","a way of helping the needy"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.THE_LI.HEALING_THE_PARALYSED_MA.PARALYSED_MAN', 'CRE.G5.THE_LI.HEALING_THE_PARALYSED_MA', 'cre', 5, 'Know the healing of the paralysed man (Mark 2:1-5) and its lessons', ARRAY['CRE.G5.THE_LI.HEALING_THE_PARALYSED_MA.a', 'CRE.G5.THE_LI.HEALING_THE_PARALYSED_MA.b']::text[], 'Says that four friends carried the man, that the crowd blocked the door so they made an opening in the roof, that Jesus saw their faith and first said that the man''s sins were forgiven. Gives lessons (faith in action, friends who help, pray when in trouble). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the story","what Jesus said first","a lesson from the story"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.THE_LI.PARABLE_OF_THE_LOST_SHEE.LOST_SHEEP', 'CRE.G5.THE_LI.PARABLE_OF_THE_LOST_SHEE', 'cre', 5, 'Know the parable of the lost sheep (Luke 15:1-7) and its lessons', ARRAY['CRE.G5.THE_LI.PARABLE_OF_THE_LOST_SHEE.a', 'CRE.G5.THE_LI.PARABLE_OF_THE_LOST_SHEE.b']::text[], 'Says that the shepherd had a hundred sheep and one was lost, that he left the ninety-nine to look for it, carried it home on his shoulders, called friends to rejoice, and that Jesus said there is joy in heaven over one sinner who repents. Gives lessons (God cares for each person, we should reach out to those who are lost). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the parable","what the shepherd did","a lesson from the parable","who the sheep stands for"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.THE_LI.SERMON_ON_THE_MOUNT.SERMON_MOUNT', 'CRE.G5.THE_LI.SERMON_ON_THE_MOUNT', 'cre', 5, 'Know the blessings of the merciful, the pure in heart and the peacemakers (Matthew 5:7-9)', ARRAY['CRE.G5.THE_LI.SERMON_ON_THE_MOUNT.a', 'CRE.G5.THE_LI.SERMON_ON_THE_MOUNT.b']::text[], 'Says what Jesus promised to the merciful (they will receive mercy), the pure in heart (they will see God) and the peacemakers (they will be called children of God), and chooses the action that applies each virtue to school and home. Does not say a peacemaker is someone who never disagrees. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["match the virtue to its promise","choose the action that shows the virtue","what a pure heart means"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.THE_LI.THE_RICH_YOUNG_MAN.RICH_YOUNG_MAN', 'CRE.G5.THE_LI.THE_RICH_YOUNG_MAN', 'cre', 5, 'Know the story of the rich young man (Matthew 19:16-22) and its lessons', ARRAY['CRE.G5.THE_LI.THE_RICH_YOUNG_MAN.a', 'CRE.G5.THE_LI.THE_RICH_YOUNG_MAN.b', 'CRE.G5.THE_LI.THE_RICH_YOUNG_MAN.c']::text[], 'Says that the young man asked what good thing to do to have eternal life, that Jesus pointed him to the commandments, that the young man said he had kept them, that Jesus told him to sell what he had, give to the poor and follow him, and that he went away sad because he had great wealth. Gives lessons (put God first, share, wealth can hold the heart). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the story","what Jesus told him","why he went away sad","a lesson from the story"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.THE_LI.A_FRIEND_AT_MIDNIGHT.FRIEND_MIDNIGHT', 'CRE.G5.THE_LI.A_FRIEND_AT_MIDNIGHT', 'cre', 5, 'Know the parable of the friend at midnight (Luke 11:5-10) and why to pray persistently', ARRAY['CRE.G5.THE_LI.A_FRIEND_AT_MIDNIGHT.a', 'CRE.G5.THE_LI.A_FRIEND_AT_MIDNIGHT.b', 'CRE.G5.THE_LI.A_FRIEND_AT_MIDNIGHT.c']::text[], 'Says that a man went to a friend at midnight to ask for three loaves for a visitor, that the friend first refused because the door was shut and the children were in bed, that he got up and gave because the man kept asking, and that Jesus taught ask, seek and knock. Gives the lesson of persistence in prayer. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the parable","why the friend finally gave","what Jesus said about asking","a lesson about prayer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.THE_CH.THE_EARLY_CHURCH.EARLY_CHURCH', 'CRE.G5.THE_CH.THE_EARLY_CHURCH', 'cre', 5, 'Know how the early Church lived in unity (Acts 2:42-47)', ARRAY['CRE.G5.THE_CH.THE_EARLY_CHURCH.a', 'CRE.G5.THE_CH.THE_EARLY_CHURCH.b', 'CRE.G5.THE_CH.THE_EARLY_CHURCH.c']::text[], 'Lists what the believers devoted themselves to (the apostles'' teaching, fellowship, breaking bread, prayer), says that they shared what they owned with anyone in need and met daily with glad hearts, and names values that keep a church united (love, sharing, forgiveness, humility, respect). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what the early believers did","a value that keeps a church united","why unity matters today"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.THE_CH.THE_LORD_S_SUPPER.LORDS_SUPPER', 'CRE.G5.THE_CH.THE_LORD_S_SUPPER', 'cre', 5, 'Know the events of the Lord''s Supper (Luke 22:14-20) and why Christians remember it', ARRAY['CRE.G5.THE_CH.THE_LORD_S_SUPPER.a', 'CRE.G5.THE_CH.THE_LORD_S_SUPPER.b', 'CRE.G5.THE_CH.THE_LORD_S_SUPPER.c']::text[], 'Says that Jesus sat with the apostles at the Passover meal, took bread, gave thanks, broke it and gave it to them, took the cup, and told them to do this in remembrance of him; knows that churches use different names (Lord''s Supper, Lord''s Table, Holy Communion, Eucharist) for the same remembrance, and that reverence, thankfulness and forgiving others are values to bring to it. No teaching of any one church is asked. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall an event of the supper","what Jesus told the apostles","a value for the Lord''s Table","the names churches use"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.THE_CH.THE_HOLY_SPIRIT.HOLY_SPIRIT', 'CRE.G5.THE_CH.THE_HOLY_SPIRIT', 'cre', 5, 'Know the gifts (1 Corinthians 12:1-11) and the fruit (Galatians 5:22-23) of the Holy Spirit', ARRAY['CRE.G5.THE_CH.THE_HOLY_SPIRIT.a', 'CRE.G5.THE_CH.THE_HOLY_SPIRIT.b', 'CRE.G5.THE_CH.THE_HOLY_SPIRIT.c']::text[], 'Tells the nine gifts (wisdom, knowledge, faith, healing, miracles, prophecy, telling spirits apart, tongues, interpreting tongues) from the nine fruit (love, joy, peace, patience, kindness, goodness, faithfulness, gentleness, self-control) and says how the fruit help Christians live in harmony. Does not mix a gift with a fruit. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["gift or fruit","which one is in the list","how a fruit helps harmony"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.THE_CH.PETER_S_MIRACULOUS_RESCU.PETER_RESCUE', 'CRE.G5.THE_CH.PETER_S_MIRACULOUS_RESCU', 'cre', 5, 'Know Peter''s rescue from prison (Acts 12:3-17) and its lessons', ARRAY['CRE.G5.THE_CH.PETER_S_MIRACULOUS_RESCU.a', 'CRE.G5.THE_CH.PETER_S_MIRACULOUS_RESCU.b']::text[], 'Says that King Herod arrested Peter and guarded him with soldiers and chains, that the church prayed earnestly for him, that an angel woke him, the chains fell off and the gate opened, that Rhoda was so glad she left him at the door, and that the believers were amazed. Gives lessons (pray for each other, God answers, have faith). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["recall a fact of the rescue","what the church was doing","what Rhoda did","a lesson from the rescue"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.CHRIST.FRIENDSHIP_FORMATION.FRIENDS', 'CRE.G5.CHRIST.FRIENDSHIP_FORMATION', 'cre', 5, 'Choose good friends and resist bad influence (Proverbs 22:24-25, 12:26)', ARRAY['CRE.G5.CHRIST.FRIENDSHIP_FORMATION.a', 'CRE.G5.CHRIST.FRIENDSHIP_FORMATION.b']::text[], 'Gives qualities of a good friend (honest, kind, respectful, responsible, hard-working, does not push you to do wrong), says what Proverbs 22:24-25 and 12:26 advise, and names a good way to refuse a friend who pushes a child to do wrong. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the quality of a good friend","what the proverb says","what to do when pushed"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.CHRIST.HUMAN_SEXUALITY.ADOLESCENCE', 'CRE.G5.CHRIST.HUMAN_SEXUALITY', 'cre', 5, 'Know the changes of adolescence and live responsibly (1 Corinthians 6:18-19)', ARRAY['CRE.G5.CHRIST.HUMAN_SEXUALITY.a', 'CRE.G5.CHRIST.HUMAN_SEXUALITY.b', 'CRE.G5.CHRIST.HUMAN_SEXUALITY.c', 'CRE.G5.CHRIST.HUMAN_SEXUALITY.d', 'CRE.G5.CHRIST.HUMAN_SEXUALITY.e']::text[], 'Names the usual changes of growing up (growing taller, body hair, a deeper voice in boys, periods in girls, new feelings), says that these are normal and that a child can talk to a parent or trusted adult, tells healthy friendships (respect, honesty, group activities, parents know) from unhealthy ones (secrecy, pressure, gifts for favours), and gives the results of unhealthy ones and ways to avoid them. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["a change of growing up","who to ask for help","healthy or unhealthy friendship","a result or a way to avoid it"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.CHRIST.SANCTITY_OF_LIFE.SANCTITY_LIFE', 'CRE.G5.CHRIST.SANCTITY_OF_LIFE', 'cre', 5, 'Know why life is sacred (Genesis 1:27, 9:6; Exodus 20:13) and how to cope with anger', ARRAY['CRE.G5.CHRIST.SANCTITY_OF_LIFE.a', 'CRE.G5.CHRIST.SANCTITY_OF_LIFE.b', 'CRE.G5.CHRIST.SANCTITY_OF_LIFE.c']::text[], 'Says that God is the giver of life, that every person is made in God''s image (Genesis 1:27), that human life is not to be taken (Genesis 9:6, Exodus 20:13), gives causes of violence against life (anger, revenge, jealousy, greed, drugs) and ways to cope with a hard feeling without harm (walk away, talk to someone, pray, count to ten). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what the verses teach","a cause of violence","how to cope with anger"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS', 'CRE.G5.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA', 'cre', 5, 'Know the effects of alcohol, drugs and substance abuse and how to say no', ARRAY['CRE.G5.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.a', 'CRE.G5.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.b', 'CRE.G5.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.c', 'CRE.G5.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.d']::text[], 'Names substances young people misuse (alcohol, bhang, miraa, cigarettes, glue and petrol sniffing), tells misuse from medicine taken as a health worker directs, gives reasons young people start (peer pressure, stress, curiosity, copying adults), effects (poor health, failing school, quarrels, crime, addiction) and values that help (self-control, courage, honesty, wisdom). Knows what Proverbs 20:1 and Ephesians 5:18 warn. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which is a misused substance","why young people start","an effect of misuse","a value that helps"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CRES.G5.CHRIST.SOCIAL_MEDIA.SOCIAL_MEDIA', 'CRE.G5.CHRIST.SOCIAL_MEDIA', 'cre', 5, 'Use social media safely and with integrity', ARRAY['CRE.G5.CHRIST.SOCIAL_MEDIA.a', 'CRE.G5.CHRIST.SOCIAL_MEDIA.b', 'CRE.G5.CHRIST.SOCIAL_MEDIA.c']::text[], 'Names platforms in common use (WhatsApp, Facebook, TikTok, YouTube, Instagram), gives advantages and disadvantages, and applies safety rules (keep passwords and addresses private, do not chat with strangers or meet them, tell a trusted adult about anything that frightens you, do not share unkind or false things). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["advantage or disadvantage","safe or unsafe action","what to do in a situation"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
