INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CRES.G5.CHRIST.SOCIAL_MEDIA.SOCIAL_MEDIA', 'CRES.G4.CHRIST.TRUTHFULNESS_TRUTHFULNES.TRUTH', 'skill', 'essential', 'Truthfulness, which applies to what we post and forward. Proposed, to confirm by a CRE teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CREATI.MY_PURPOSE_TALENTS_AND_A.TALENTS_PARABLE.M_TAL_MONEY_ONLY', 'CRES.G5.CREATI.MY_PURPOSE_TALENTS_AND_A.TALENTS_PARABLE', 'Thinks the lesson is only about money.', '{"question":"What does the parable of the talents teach a Grade 5 learner?","wrong_answer":"Keep your money safe and never spend it","correct_answer":"Use the gifts and abilities God has given you"}'::jsonb, 'A talent in the story was a large sum of money, so the child reads the story as advice about savings.', 'Offer "Keep your money safe and never spend it" beside "Use the gifts and abilities God has given you" and ask the child to choose.', 'Ask what the servants did with what they were given. Then name other gifts: singing, kindness, farming, drawing, helping.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CREATI.MY_PURPOSE_TALENTS_AND_A.TALENTS_PARABLE.M_TAL_UNFAIR', 'CRES.G5.CREATI.MY_PURPOSE_TALENTS_AND_A.TALENTS_PARABLE', 'Thinks the master was unfair, or that the third servant was punished for having least.', '{"question":"Why was the third servant blamed?","wrong_answer":"He was given less than the others","correct_answer":"He buried his talent and did not use it"}'::jsonb, 'The child notices the amounts (five, two, one) and thinks that having less is the fault.', 'Offer "He was given less than the others" beside "He buried his talent and did not use it" and ask the child to choose.', 'Reread Matthew 25:15, "each according to his ability", then the servant''s own words about fear and the buried talent.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CREATI.MY_PURPOSE_TALENTS_AND_A.TALENTS_PARABLE.M_TAL_NUMBERS', 'CRES.G5.CREATI.MY_PURPOSE_TALENTS_AND_A.TALENTS_PARABLE', 'Mixes up the numbers of talents given and gained.', '{"question":"How many talents did the first servant gain?","wrong_answer":"Two more","correct_answer":"Five more"}'::jsonb, 'The child remembers five, two and one but not which servant gained what.', 'Offer "Two more" beside "Five more" and ask the child to choose.', 'Draw three columns: given, gained, total. Fill them from Matthew 25:16-18.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CREATI.MY_PURPOSE_TALENTS_AND_A.PURPOSE_VERSES.M_PUR_SHOW_OFF', 'CRES.G5.CREATI.MY_PURPOSE_TALENTS_AND_A.PURPOSE_VERSES', 'Thinks gifts are given so that a person can be admired or win.', '{"question":"According to 1 Peter 4:10, what should each person do with the gift received?","wrong_answer":"Show it off so others admire you","correct_answer":"Use it to serve others"}'::jsonb, 'Children see talent shows and prizes and link gifts to winning.', 'Offer "Show it off so others admire you" beside "Use it to serve others" and ask the child to choose.', 'Read 1 Peter 4:10 aloud and ask who benefits when a gift is used to serve.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CREATI.MY_PURPOSE_TALENTS_AND_A.PURPOSE_VERSES.M_PUR_FEW_ONLY', 'CRES.G5.CREATI.MY_PURPOSE_TALENTS_AND_A.PURPOSE_VERSES', 'Thinks God has a purpose only for adults or only for people with big talents.', '{"question":"What does Jeremiah 29:11 say about God''s plans?","wrong_answer":"God has plans only for adults","correct_answer":"God has plans for welfare, a future and hope"}'::jsonb, 'The child thinks purpose belongs to jobs and grown-ups.', 'Offer "God has plans only for adults" beside "God has plans for welfare, a future and hope" and ask the child to choose.', 'Read Jeremiah 29:11 and ask who God is speaking about. Say that a Grade 5 child is included.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CREATI.MY_PURPOSE_TALENTS_AND_A.PURPOSE_VERSES.M_PUR_OWN_MAKING', 'CRES.G5.CREATI.MY_PURPOSE_TALENTS_AND_A.PURPOSE_VERSES', 'Thinks a person''s abilities come only from the person''s own effort.', '{"question":"According to James 1:17, where does every good gift come from?","wrong_answer":"From a person''s own hard work alone","correct_answer":"From God, the Father of lights"}'::jsonb, 'Effort is praised at school, so the giver is forgotten.', 'Offer "From a person''s own hard work alone" beside "From God, the Father of lights" and ask the child to choose.', 'Read James 1:17. Say that work matters, but that the ability to work and learn is a gift too.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CREATI.MY_PURPOSE_TALENTS_AND_A.TALENTS_PARABLE.M_C5_TAL_REWARD_SAME', 'CRES.G5.CREATI.MY_PURPOSE_TALENTS_AND_A.TALENTS_PARABLE', 'Thinks the first two servants were praised differently because one gained more.', '{"question":"What did the master say to the servant who gained two more talents (Matthew 25:23)?","wrong_answer":"Less praise, because he gained less","correct_answer":"\"Well done, good and faithful servant\", the same as the first"}'::jsonb, 'The child expects praise to match the amount.', 'Offer "Less praise, because he gained less" beside ""Well done, good and faithful servant", the same as the first" and ask the child to choose.', 'Read 25:21 and 25:23 side by side: the same words. The master praised faithfulness, not the size.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CREATI.MY_PURPOSE_TALENTS_AND_A.PURPOSE_VERSES.M_C5_PUR_FIXED_JOB', 'CRES.G5.CREATI.MY_PURPOSE_TALENTS_AND_A.PURPOSE_VERSES', 'Thinks God''s purpose means one fixed job chosen at birth, so a child need not work hard.', '{"question":"If God has a plan for you (Jeremiah 29:11), should you still work hard at school?","wrong_answer":"No, God''s plan will happen anyway","correct_answer":"Yes: God''s plan gives hope, and we use our gifts faithfully"}'::jsonb, 'The child hears plan as a finished timetable and stops seeing his own part.', 'Offer "No, God''s plan will happen anyway" beside "Yes: God''s plan gives hope, and we use our gifts faithfully" and ask the child to choose.', 'Join Jeremiah 29:11 with 1 Peter 4:10: God gives the hope; we use the gifts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CREATI.WORK.STEWARDSHIP.M_STW_RULE_HARM', 'CRES.G5.CREATI.WORK.STEWARDSHIP', 'Reads "rule over" in Genesis 1:26 as permission to use up or harm creation.', '{"question":"What does it mean to rule over the animals and plants in Genesis 1:26 and 2:15?","wrong_answer":"Use them as we like, even if they are finished","correct_answer":"Look after them as God''s caretaker"}'::jsonb, 'The word rule is heard as power, not as care.', 'Offer "Use them as we like, even if they are finished" beside "Look after them as God''s caretaker" and ask the child to choose.', 'Read Genesis 2:15 beside it: "to work it and take care of it".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CREATI.WORK.STEWARDSHIP.M_STW_WORK_PUNISHMENT', 'CRES.G5.CREATI.WORK.STEWARDSHIP', 'Thinks work is only a punishment.', '{"question":"When did God first give human beings work in the Bible?","wrong_answer":"After they did wrong, as a punishment","correct_answer":"In the garden, before they did wrong"}'::jsonb, 'Work is hard at times, so the child thinks it began as a punishment.', 'Offer "After they did wrong, as a punishment" beside "In the garden, before they did wrong" and ask the child to choose.', 'Compare Genesis 2:15 (work in the garden) with Genesis 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CREATI.WORK.STEWARDSHIP.M_STW_HOME_ONLY', 'CRES.G5.CREATI.WORK.STEWARDSHIP', 'Gives a home chore when asked for a role at church, as if a child''s roles were only at home.', '{"question":"Which one is a role a child can do at church?","wrong_answer":"Cleaning the compound at home","correct_answer":"Helping to keep the church compound clean"}'::jsonb, 'The child lists chores for home and misses school and church roles.', 'Offer "Cleaning the compound at home" beside "Helping to keep the church compound clean" and ask the child to choose.', 'Make three lists on the board: home, school and church.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CREATI.WORK.CHILD_LABOUR.M_CL_CHORES_ARE_LABOUR', 'CRES.G5.CREATI.WORK.CHILD_LABOUR', 'Thinks every chore at home is child labour.', '{"question":"Which of these is child labour?","wrong_answer":"Sweeping the room after school","correct_answer":"Carrying heavy loads for hours instead of going to school"}'::jsonb, 'The child hears that work for children is wrong and applies it to every chore.', 'Offer "Sweeping the room after school" beside "Carrying heavy loads for hours instead of going to school" and ask the child to choose.', 'Sort tasks by three questions: is it safe, does it suit my age, does it stop me from school or rest?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CREATI.WORK.CHILD_LABOUR.M_CL_LABOUR_IS_GOOD', 'CRES.G5.CREATI.WORK.CHILD_LABOUR', 'Thinks child labour is good because it teaches a child to work or earns money.', '{"question":"What is a common effect of child labour?","wrong_answer":"The child learns more at school","correct_answer":"The child misses school and can be hurt"}'::jsonb, 'The child links any work with growing up well.', 'Offer "The child learns more at school" beside "The child misses school and can be hurt" and ask the child to choose.', 'Name a child who herds all day and cannot read. Ask what the child lost.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CREATI.WORK.CHILD_LABOUR.M_CL_REPORT_EMPLOYER', 'CRES.G5.CREATI.WORK.CHILD_LABOUR', 'Thinks a child forced to work should tell the employer or keep quiet.', '{"question":"Whom should a child tell if he is forced to work?","wrong_answer":"The person who forces him","correct_answer":"A trusted adult such as a teacher, the chief or a parent"}'::jsonb, 'The child fears the person in charge.', 'Offer "The person who forces him" beside "A trusted adult such as a teacher, the chief or a parent" and ask the child to choose.', 'Make a list of safe adults together, including the Childline Kenya line 116.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CREATI.WORK.CHILD_LABOUR.M_CL_CAUSE_LAZY', 'CRES.G5.CREATI.WORK.CHILD_LABOUR', 'Blames the child or says children work only because they are lazy at school.', '{"question":"What is one cause of child labour in many places?","wrong_answer":"Children who like to be lazy","correct_answer":"Poverty in the family"}'::jsonb, 'The child blames the child instead of the conditions.', 'Offer "Children who like to be lazy" beside "Poverty in the family" and ask the child to choose.', 'Ask what a family with no food might feel it must do.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CREATI.WORK.STEWARDSHIP.M_C5_STW_ADULT_ROLES', 'CRES.G5.CREATI.WORK.STEWARDSHIP', 'Lists only adult jobs, such as paying fees, when asked for a child''s roles at home.', '{"question":"Name one role a Grade 5 child has at home.","wrong_answer":"Paying the school fees","correct_answer":"Washing dishes or fetching water"}'::jsonb, 'The child names the big jobs he sees adults do.', 'Offer "Paying the school fees" beside "Washing dishes or fetching water" and ask the child to choose.', 'Make three columns, home, school, church, and fill them only with things a ten-year-old can do.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CREATI.THE_FALL_OF_MAN.FALL_OF_MAN.M_FALL_APPLE', 'CRES.G5.CREATI.THE_FALL_OF_MAN.FALL_OF_MAN', 'Names the forbidden fruit as an apple, though Genesis 3 does not name the fruit.', '{"question":"What does Genesis 3 say about the kind of fruit that was eaten?","wrong_answer":"It was an apple","correct_answer":"The Bible does not name the fruit"}'::jsonb, 'Pictures and stories name the fruit, and the child remembers the picture.', 'Offer "It was an apple" beside "The Bible does not name the fruit" and ask the child to choose.', 'Read Genesis 3:6 and look for the name of the fruit together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CREATI.THE_FALL_OF_MAN.FALL_OF_MAN.M_FALL_ONE_PERSON', 'CRES.G5.CREATI.THE_FALL_OF_MAN.FALL_OF_MAN', 'Thinks only one person ate or that the other was not involved.', '{"question":"Who ate the fruit God had forbidden?","wrong_answer":"Only the woman","correct_answer":"The woman, who then gave some to her husband, and he ate"}'::jsonb, 'The child remembers the woman and the serpent but not the man.', 'Offer "Only the woman" beside "The woman, who then gave some to her husband, and he ate" and ask the child to choose.', 'Read Genesis 3:6 and count who ate.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CREATI.THE_FALL_OF_MAN.FALL_OF_MAN.M_FALL_SERPENT_TRUE', 'CRES.G5.CREATI.THE_FALL_OF_MAN.FALL_OF_MAN', 'Thinks the serpent told the truth or was a friend.', '{"question":"What did the serpent do?","wrong_answer":"He told them the truth about God","correct_answer":"He tempted them to doubt what God said"}'::jsonb, 'The child follows the serpent''s smooth words in the story.', 'Offer "He told them the truth about God" beside "He tempted them to doubt what God said" and ask the child to choose.', 'Compare what God said in Genesis 2:17 with what the serpent said in 3:4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CREATI.THE_FALL_OF_MAN.FALL_OF_MAN.M_FALL_BLAME', 'CRES.G5.CREATI.THE_FALL_OF_MAN.FALL_OF_MAN', 'Thinks blaming someone else is an acceptable answer to wrong done.', '{"question":"After eating the fruit, the man blamed the woman. What should a person do when he does wrong?","wrong_answer":"Blame someone else","correct_answer":"Admit it honestly and say sorry"}'::jsonb, 'The child sees blame as a way out, as the man did.', 'Offer "Blame someone else" beside "Admit it honestly and say sorry" and ask the child to choose.', 'Read Genesis 3:12-13 and ask whether blaming helped.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CREATI.FAMILY_UNITY.FAMILY_UNITY.M_FU_NO_QUARREL', 'CRES.G5.CREATI.FAMILY_UNITY.FAMILY_UNITY', 'Thinks a united family never disagrees.', '{"question":"What is family unity?","wrong_answer":"Never disagreeing about anything","correct_answer":"Living together in love, helping and forgiving one another"}'::jsonb, 'The child sees unity as the absence of noise.', 'Offer "Never disagreeing about anything" beside "Living together in love, helping and forgiving one another" and ask the child to choose.', 'Read Colossians 3:13-14: bear with each other and forgive. That assumes there are things to forgive.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CREATI.FAMILY_UNITY.FAMILY_UNITY.M_FU_PARENTS_ONLY', 'CRES.G5.CREATI.FAMILY_UNITY.FAMILY_UNITY', 'Thinks only parents are responsible for a happy family.', '{"question":"Who can help to make a family happy?","wrong_answer":"Only the parents","correct_answer":"Every member of the family, including children"}'::jsonb, 'The child thinks children only receive.', 'Offer "Only the parents" beside "Every member of the family, including children" and ask the child to choose.', 'List three things a child can do: chores, kind words, obedience.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CREATI.FAMILY_UNITY.FAMILY_UNITY.M_FU_FORGIVE_PRETEND', 'CRES.G5.CREATI.FAMILY_UNITY.FAMILY_UNITY', 'Thinks forgiving means pretending nothing happened or that wrong was right.', '{"question":"What does it mean to forgive a family member?","wrong_answer":"To pretend nothing wrong was done","correct_answer":"To let go of the anger and choose to love again"}'::jsonb, 'The child mixes forgiving with ignoring.', 'Offer "To pretend nothing wrong was done" beside "To let go of the anger and choose to love again" and ask the child to choose.', 'Say what Colossians 3:13 asks: forgive as the Lord forgave you.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CREATI.FAMILY_UNITY.FAMILY_UNITY.M_C5_FU_RICH_HAPPY', 'CRES.G5.CREATI.FAMILY_UNITY.FAMILY_UNITY', 'Thinks a family is united only if it has money, and that poor families cannot be happy.', '{"question":"What makes a family united?","wrong_answer":"Having a lot of money","correct_answer":"Love, respect, forgiveness and helping one another"}'::jsonb, 'The child links happiness with the things advertisements show.', 'Offer "Having a lot of money" beside "Love, respect, forgiveness and helping one another" and ask the child to choose.', 'Read Colossians 3:13-14: what binds a family is love. List things that cost nothing and build unity.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.THE_BIBLE_AS_A_GUIDE.BIBLE_GUIDE.M_BG_CHURCH_ONLY', 'CRES.G5.THE_BI.THE_BIBLE_AS_A_GUIDE.BIBLE_GUIDE', 'Thinks the Bible is useful only inside church.', '{"question":"Where does the Bible guide a Christian?","wrong_answer":"Only at church on Sunday","correct_answer":"At home, school, church and in the community every day"}'::jsonb, 'The child meets the Bible mostly in church.', 'Offer "Only at church on Sunday" beside "At home, school, church and in the community every day" and ask the child to choose.', 'Ask for a verse that helps at home or at school.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.THE_BIBLE_AS_A_GUIDE.BIBLE_GUIDE.M_BG_READ_ONCE', 'CRES.G5.THE_BI.THE_BIBLE_AS_A_GUIDE.BIBLE_GUIDE', 'Thinks reading the Bible once is enough.', '{"question":"What does Joshua 1:8 ask about God''s word?","wrong_answer":"Read it once and then keep it safe","correct_answer":"Think about it day and night and do what it says"}'::jsonb, 'The child thinks of reading as finishing a book.', 'Offer "Read it once and then keep it safe" beside "Think about it day and night and do what it says" and ask the child to choose.', 'Read Joshua 1:8 and Psalm 1:2, "his delight is in the law of the Lord".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.THE_BIBLE_AS_A_GUIDE.BIBLE_GUIDE.M_BG_PSALM_TREE', 'CRES.G5.THE_BI.THE_BIBLE_AS_A_GUIDE.BIBLE_GUIDE', 'Picks a wall or a rock for what Psalm 1:3 compares a person who delights in God''s word to, instead of a tree by streams of water.', '{"question":"In Psalm 1:3, the person who delights in God''s word is like...","wrong_answer":"A strong wall","correct_answer":"A tree planted by streams of water"}'::jsonb, 'The child remembers an image from the Bible but not which.', 'Offer "A strong wall" beside "A tree planted by streams of water" and ask the child to choose.', 'Read Psalm 1:3 and draw the tree.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.THE_BIBLE_AS_A_GUIDE.BIBLE_GUIDE.M_C5_BG_ONLY_RULES', 'CRES.G5.THE_BI.THE_BIBLE_AS_A_GUIDE.BIBLE_GUIDE', 'Thinks the Bible is only a book of rules, not also comfort, history, songs and promises.', '{"question":"Which of these is a use of the Bible in society today?","wrong_answer":"Only to punish people who break rules","correct_answer":"To guide, comfort, teach and inspire, in homes, schools, courts and churches"}'::jsonb, 'The child has heard the Bible quoted mostly when someone is corrected.', 'Offer "Only to punish people who break rules" beside "To guide, comfort, teach and inspire, in homes, schools, courts and churches" and ask the child to choose.', 'Show different parts: Psalms (songs), Gospels (Jesus'' life), Proverbs (wisdom). Ask where each is used.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.BIBLE_STORIES_PETER_AND_.PETER_JOHN.M_PJ_DENIED', 'CRES.G5.THE_BI.BIBLE_STORIES_PETER_AND_.PETER_JOHN', 'Mixes this story with Peter denying Jesus and thinks Peter was afraid to speak.', '{"question":"How did Peter speak to the rulers in Acts 4?","wrong_answer":"He was afraid and said he did not know Jesus","correct_answer":"He spoke boldly, filled with the Holy Spirit"}'::jsonb, 'The child remembers Peter''s denial in the courtyard.', 'Offer "He was afraid and said he did not know Jesus" beside "He spoke boldly, filled with the Holy Spirit" and ask the child to choose.', 'Read Acts 4:8 and 4:13: "filled with the Holy Spirit", "the courage of Peter and John".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.BIBLE_STORIES_PETER_AND_.PETER_JOHN.M_PJ_STOPPED', 'CRES.G5.THE_BI.BIBLE_STORIES_PETER_AND_.PETER_JOHN', 'Thinks Peter told the rulers there are many ways to be saved, missing Acts 4:12: no other name.', '{"question":"What did Peter say about salvation in Acts 4:12?","wrong_answer":"That there are many ways and names","correct_answer":"That there is no salvation in any other name than Jesus"}'::jsonb, 'The child expects the story to end with the apostles giving in.', 'Offer "That there are many ways and names" beside "That there is no salvation in any other name than Jesus" and ask the child to choose.', 'Read Acts 4:12 aloud, then verse 13.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.BIBLE_STORIES_PETER_AND_.PETER_JOHN.M_PJ_NO_POWER', 'CRES.G5.THE_BI.BIBLE_STORIES_PETER_AND_.PETER_JOHN', 'Thinks that Peter and John did the healing by their own power.', '{"question":"By whose power did Peter say the man had been healed?","wrong_answer":"By the power of Peter and John","correct_answer":"By the name of Jesus Christ"}'::jsonb, 'The child sees the apostles as the actors and forgets the power given.', 'Offer "By the power of Peter and John" beside "By the name of Jesus Christ" and ask the child to choose.', 'Read Acts 4:10.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.BIBLE_STORIES_PETER_AND_.PETER_JOHN.M_C5_PJ_OBEYED_RULERS', 'CRES.G5.THE_BI.BIBLE_STORIES_PETER_AND_.PETER_JOHN', 'Thinks Peter and John agreed to stop speaking about Jesus when the rulers ordered them.', '{"question":"What did Peter and John answer when told not to speak about Jesus (Acts 4:19-20)?","wrong_answer":"They agreed to keep quiet","correct_answer":"\"We cannot help speaking about what we have seen and heard\""}'::jsonb, 'The child thinks one must always obey rulers.', 'Offer "They agreed to keep quiet" beside ""We cannot help speaking about what we have seen and heard"" and ask the child to choose.', 'Read Acts 4:19-20 aloud: they asked whether to obey God or people.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.KING_SOLOMON_THE_WISE_RU.SOLOMON.M_SOL_WRONG_MOTHER', 'CRES.G5.THE_BI.KING_SOLOMON_THE_WISE_RU.SOLOMON', 'Thinks the woman who agreed to divide the child was the real mother.', '{"question":"Which woman did Solomon decide was the real mother?","wrong_answer":"The woman who said, \"Divide him\"","correct_answer":"The woman who said, \"Give her the living child\""}'::jsonb, 'The child follows the first voice and misses the love in giving up.', 'Offer "The woman who said, "Divide him"" beside "The woman who said, "Give her the living child"" and ask the child to choose.', 'Reread 1 Kings 3:26-27 and ask who loved the child.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.KING_SOLOMON_THE_WISE_RU.SOLOMON.M_SOL_CUT', 'CRES.G5.THE_BI.KING_SOLOMON_THE_WISE_RU.SOLOMON', 'Thinks Solomon really had the baby cut in two.', '{"question":"What happened to the baby?","wrong_answer":"Solomon had him cut in two","correct_answer":"He was given to his real mother alive"}'::jsonb, 'The child misses that the order was a test.', 'Offer "Solomon had him cut in two" beside "He was given to his real mother alive" and ask the child to choose.', 'Read verse 27: "Give her the living child".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.KING_SOLOMON_THE_WISE_RU.SOLOMON.M_SOL_STRONG_NOT_WISE', 'CRES.G5.THE_BI.KING_SOLOMON_THE_WISE_RU.SOLOMON', 'Thinks Solomon''s wisdom meant strength, riches or force.', '{"question":"What does Proverbs 9:10 say is the beginning of wisdom?","wrong_answer":"Having riches and power","correct_answer":"Respect and reverence for the Lord"}'::jsonb, 'The child sees a king and pictures power.', 'Offer "Having riches and power" beside "Respect and reverence for the Lord" and ask the child to choose.', 'Read Proverbs 9:10 and ask what Solomon asked from God in 1 Kings 3:9.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.KING_SOLOMON_THE_WISE_RU.SOLOMON.M_C5_SOL_ASKED_RICHES', 'CRES.G5.THE_BI.KING_SOLOMON_THE_WISE_RU.SOLOMON', 'Thinks Solomon asked God for riches and long life.', '{"question":"What did Solomon ask God for (1 Kings 3:9)?","wrong_answer":"Riches and a long life","correct_answer":"A discerning heart to judge the people and tell right from wrong"}'::jsonb, 'The child guesses what a king would want.', 'Offer "Riches and a long life" beside "A discerning heart to judge the people and tell right from wrong" and ask the child to choose.', 'Read 1 Kings 3:9-11: God was pleased because Solomon did not ask for riches.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.NOAH_AND_HIS_SONS.NOAH_SONS.M_NS_NAMES', 'CRES.G5.THE_BI.NOAH_AND_HIS_SONS.NOAH_SONS', 'Names Cain, Abel and Seth (Adam''s sons) as Noah''s sons, instead of Shem, Ham and Japheth.', '{"question":"Which are the names of Noah''s three sons?","wrong_answer":"Cain, Abel and Seth","correct_answer":"Shem, Ham and Japheth"}'::jsonb, 'The child mixes the first sons in Genesis with those after the flood.', 'Offer "Cain, Abel and Seth" beside "Shem, Ham and Japheth" and ask the child to choose.', 'Read Genesis 9:18 and write the three names on a card.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.NOAH_AND_HIS_SONS.NOAH_SONS.M_NS_HAM_COVERED', 'CRES.G5.THE_BI.NOAH_AND_HIS_SONS.NOAH_SONS', 'Thinks Ham covered his father.', '{"question":"Which sons covered their father with a garment?","wrong_answer":"Ham","correct_answer":"Shem and Japheth"}'::jsonb, 'The child mixes who saw with who covered.', 'Offer "Ham" beside "Shem and Japheth" and ask the child to choose.', 'Read Genesis 9:22-23 slowly, naming each son.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.NOAH_AND_HIS_SONS.NOAH_SONS.M_NS_FIRST_FLOOD', 'CRES.G5.THE_BI.NOAH_AND_HIS_SONS.NOAH_SONS', 'Thinks the story is about the flood itself.', '{"question":"What is the story in Genesis 9:18-23 mostly about?","wrong_answer":"How Noah built the ark","correct_answer":"How Noah''s sons treated their father"}'::jsonb, 'The child knows Noah from the ark and the flood.', 'Offer "How Noah built the ark" beside "How Noah''s sons treated their father" and ask the child to choose.', 'Say that the flood is over in this reading.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.NOAH_AND_HIS_SONS.RESPECT_ELDERLY.M_RE_AGREE', 'CRES.G5.THE_BI.NOAH_AND_HIS_SONS.RESPECT_ELDERLY', 'Thinks respect means agreeing with everything an older person says.', '{"question":"Which shows respect to an older person?","wrong_answer":"Agreeing with everything and never asking a question","correct_answer":"Greeting politely and listening carefully"}'::jsonb, 'The child confuses respect with silence.', 'Offer "Agreeing with everything and never asking a question" beside "Greeting politely and listening carefully" and ask the child to choose.', 'Ask whether a polite question is respectful.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.NOAH_AND_HIS_SONS.RESPECT_ELDERLY.M_RE_RELATIVES', 'CRES.G5.THE_BI.NOAH_AND_HIS_SONS.RESPECT_ELDERLY', 'Thinks respect is only for relatives.', '{"question":"To whom should a child show respect?","wrong_answer":"Only grandparents and relatives","correct_answer":"Every older person, including neighbours and strangers"}'::jsonb, 'The child ties respect to the family.', 'Offer "Only grandparents and relatives" beside "Every older person, including neighbours and strangers" and ask the child to choose.', 'Give a story of an older neighbour carrying water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.NOAH_AND_HIS_SONS.RESPECT_ELDERLY.M_RE_PAYMENT', 'CRES.G5.THE_BI.NOAH_AND_HIS_SONS.RESPECT_ELDERLY', 'Thinks you help an older person only if you are paid or thanked.', '{"question":"Why do Christians respect and help the elderly?","wrong_answer":"So that they pay or reward us","correct_answer":"Because it pleases God and is the right thing to do"}'::jsonb, 'The child does tasks for rewards.', 'Offer "So that they pay or reward us" beside "Because it pleases God and is the right thing to do" and ask the child to choose.', 'Ask what Shem and Japheth gained.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.NOAH_AND_HIS_SONS.NOAH_SONS.M_C5_NS_SAW_TOLD_PRAISE', 'CRES.G5.THE_BI.NOAH_AND_HIS_SONS.NOAH_SONS', 'Thinks Ham was praised for telling his brothers what he saw.', '{"question":"Why was it wrong for Ham to tell his brothers about their father (Genesis 9:22)?","wrong_answer":"It was not wrong; he was praised","correct_answer":"He shamed his father instead of covering him"}'::jsonb, 'Telling others news sounds helpful to a child.', 'Offer "It was not wrong; he was praised" beside "He shamed his father instead of covering him" and ask the child to choose.', 'Contrast: Ham told; Shem and Japheth walked in backwards and covered him. Which honoured the father?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.NOAH_AND_HIS_SONS.RESPECT_ELDERLY.M_C5_RE_IGNORE_POOR', 'CRES.G5.THE_BI.NOAH_AND_HIS_SONS.RESPECT_ELDERLY', 'Thinks a poor or sick old person deserves less respect than a rich one.', '{"question":"Mzee Otieno is old and poor. How should a child treat him?","wrong_answer":"Less politely than a rich elder","correct_answer":"With the same respect as any elder"}'::jsonb, 'The child sees how some adults treat the poor and copies it.', 'Offer "Less politely than a rich elder" beside "With the same respect as any elder" and ask the child to choose.', 'Read Leviticus 19:32: rise in the presence of the aged. Respect is for age, not money.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.A_HAND_WRITES_ON_THE_WAL.WRITING_ON_WALL.M_WW_KING', 'CRES.G5.THE_BI.A_HAND_WRITES_ON_THE_WAL.WRITING_ON_WALL', 'Names Nebuchadnezzar, Belshazzar''s father, as the king who held the feast.', '{"question":"Which king held the feast in Daniel 5?","wrong_answer":"Nebuchadnezzar","correct_answer":"Belshazzar"}'::jsonb, 'Nebuchadnezzar is better known.', 'Offer "Nebuchadnezzar" beside "Belshazzar" and ask the child to choose.', 'Read Daniel 5:1 and write the name.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.A_HAND_WRITES_ON_THE_WAL.WRITING_ON_WALL.M_WW_WHO_WROTE', 'CRES.G5.THE_BI.A_HAND_WRITES_ON_THE_WAL.WRITING_ON_WALL', 'Thinks Daniel wrote the words or that a person wrote them.', '{"question":"Whose hand wrote on the wall?","wrong_answer":"Daniel''s hand","correct_answer":"A human hand that appeared, with no body"}'::jsonb, 'The child skips the first lines of the passage.', 'Offer "Daniel''s hand" beside "A human hand that appeared, with no body" and ask the child to choose.', 'Read Daniel 5:5.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.A_HAND_WRITES_ON_THE_WAL.WRITING_ON_WALL.M_WW_VESSELS', 'CRES.G5.THE_BI.A_HAND_WRITES_ON_THE_WAL.WRITING_ON_WALL', 'Thinks the holy vessels were used well at the feast.', '{"question":"Why was it wrong to use the gold and silver vessels at the feast?","wrong_answer":"They were too heavy to carry","correct_answer":"They were holy vessels from God''s temple and were used to drink wine and praise idols"}'::jsonb, 'The child sees a feast but not the insult to God.', 'Offer "They were too heavy to carry" beside "They were holy vessels from God''s temple and were used to drink wine and praise idols" and ask the child to choose.', 'Read Daniel 5:2-4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.A_HAND_WRITES_ON_THE_WAL.WRITING_ON_WALL.M_WW_MEANING', 'CRES.G5.THE_BI.A_HAND_WRITES_ON_THE_WAL.WRITING_ON_WALL', 'Thinks the writing promised the kingdom would grow, when it said the days were numbered, the king weighed and found wanting, the kingdom divided.', '{"question":"What did the writing say about the king''s kingdom?","wrong_answer":"It would grow bigger","correct_answer":"It was numbered, weighed and divided"}'::jsonb, 'The child does not follow the three words.', 'Offer "It would grow bigger" beside "It was numbered, weighed and divided" and ask the child to choose.', 'Read Daniel 5:25-28 and match mene, tekel and peres.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.A_HAND_WRITES_ON_THE_WAL.HUMILITY_DANIEL.M_HD_WEAK', 'CRES.G5.THE_BI.A_HAND_WRITES_ON_THE_WAL.HUMILITY_DANIEL', 'Thinks humility means being weak or thinking nothing of yourself.', '{"question":"What is humility?","wrong_answer":"Being weak and having no opinions","correct_answer":"Not boasting, and treating others with respect"}'::jsonb, 'The child hears humble and thinks of poor or small.', 'Offer "Being weak and having no opinions" beside "Not boasting, and treating others with respect" and ask the child to choose.', 'Ask whether Daniel was weak when he spoke to the king.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.A_HAND_WRITES_ON_THE_WAL.HUMILITY_DANIEL.M_HD_PROUD_BELSHAZZAR', 'CRES.G5.THE_BI.A_HAND_WRITES_ON_THE_WAL.HUMILITY_DANIEL', 'Thinks the king was humble.', '{"question":"Who showed pride in the story?","wrong_answer":"Daniel","correct_answer":"King Belshazzar"}'::jsonb, 'The child misreads who did what.', 'Offer "Daniel" beside "King Belshazzar" and ask the child to choose.', 'Read Daniel 5:22-23, where Daniel says Belshazzar did not humble himself.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.A_HAND_WRITES_ON_THE_WAL.HUMILITY_DANIEL.M_HD_REWARD', 'CRES.G5.THE_BI.A_HAND_WRITES_ON_THE_WAL.HUMILITY_DANIEL', 'Thinks Daniel served the king for a reward.', '{"question":"What did Daniel say to the king''s gifts and rewards?","wrong_answer":"He asked for more rewards","correct_answer":"He said the king could keep the gifts, and he read the writing anyway"}'::jsonb, 'The child expects the hero to get paid.', 'Offer "He asked for more rewards" beside "He said the king could keep the gifts, and he read the writing anyway" and ask the child to choose.', 'Read Daniel 5:17.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.A_HAND_WRITES_ON_THE_WAL.HUMILITY_DANIEL.M_C5_HD_HUMBLE_SILENT', 'CRES.G5.THE_BI.A_HAND_WRITES_ON_THE_WAL.HUMILITY_DANIEL', 'Thinks a humble person never speaks the truth to someone more powerful.', '{"question":"Daniel told the king hard words (Daniel 5:22-23). Was that humble?","wrong_answer":"No, humble people stay silent","correct_answer":"Yes: humble people do not boast but still speak the truth"}'::jsonb, 'The child pictures humility as being quiet and small.', 'Offer "No, humble people stay silent" beside "Yes: humble people do not boast but still speak the truth" and ask the child to choose.', 'Read Daniel 5:17 and 5:22: Daniel refused rewards (humble) and spoke the truth (brave).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.MOUNT_CARMEL_CONTEST.CARMEL.M_CAR_BAAL_ANSWERED', 'CRES.G5.THE_BI.MOUNT_CARMEL_CONTEST.CARMEL', 'Thinks Baal answered first.', '{"question":"What happened when the prophets of Baal called on Baal?","wrong_answer":"Baal sent fire","correct_answer":"There was no answer"}'::jsonb, 'The child expects both sides to be equal.', 'Offer "Baal sent fire" beside "There was no answer" and ask the child to choose.', 'Read 1 Kings 18:26, "there was no voice".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.MOUNT_CARMEL_CONTEST.CARMEL.M_CAR_ELIJAH_LIT', 'CRES.G5.THE_BI.MOUNT_CARMEL_CONTEST.CARMEL', 'Thinks Elijah lit the fire.', '{"question":"Who sent the fire onto Elijah''s altar?","wrong_answer":"Elijah lit it himself","correct_answer":"The Lord sent it from heaven"}'::jsonb, 'The child pictures a prophet and not the Lord acting.', 'Offer "Elijah lit it himself" beside "The Lord sent it from heaven" and ask the child to choose.', 'Read verse 38: "the fire of the Lord fell".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.MOUNT_CARMEL_CONTEST.CARMEL.M_CAR_NUMBERS', 'CRES.G5.THE_BI.MOUNT_CARMEL_CONTEST.CARMEL', 'Says there were twelve prophets of Baal, mixing them with the twelve stones of Elijah''s altar, instead of 450.', '{"question":"How many prophets of Baal were there on Mount Carmel?","wrong_answer":"Twelve","correct_answer":"Four hundred and fifty"}'::jsonb, 'Numbers in the story: 450 prophets, twelve stones, four jars of water.', 'Offer "Twelve" beside "Four hundred and fifty" and ask the child to choose.', 'Make a card for each number and what it counted.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.MOUNT_CARMEL_CONTEST.TRUE_GOD.M_TG_IDOL_POWER', 'CRES.G5.THE_BI.MOUNT_CARMEL_CONTEST.TRUE_GOD', 'Thinks an idol can hear and help.', '{"question":"What can an idol made of wood or stone do?","wrong_answer":"Hear prayers and answer them","correct_answer":"Nothing, because it cannot hear, see or speak"}'::jsonb, 'The child hears about gods in some stories as strong.', 'Offer "Hear prayers and answer them" beside "Nothing, because it cannot hear, see or speak" and ask the child to choose.', 'Compare Carmel: the idol did not answer, the Lord did.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.MOUNT_CARMEL_CONTEST.TRUE_GOD.M_TG_SECRET_GROUP', 'CRES.G5.THE_BI.MOUNT_CARMEL_CONTEST.TRUE_GOD', 'Thinks a group that asks for secrecy and harmful acts is safe to join.', '{"question":"A group tells Mwende to join secret meetings and not to tell her parents. What should she do?","wrong_answer":"Join, because they are friendly","correct_answer":"Tell her parents or a trusted adult and not join"}'::jsonb, 'The child values belonging and trusts a friendly invitation.', 'Offer "Join, because they are friendly" beside "Tell her parents or a trusted adult and not join" and ask the child to choose.', 'Say that secrets from parents are a warning sign.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.MOUNT_CARMEL_CONTEST.TRUE_GOD.M_TG_MANY_GODS', 'CRES.G5.THE_BI.MOUNT_CARMEL_CONTEST.TRUE_GOD', 'Thinks a Christian can worship the Lord and other gods together.', '{"question":"What do the Ten Commandments say about other gods?","wrong_answer":"Worship the Lord and also other gods","correct_answer":"Do not have other gods before the Lord, and do not make idols to bow down to"}'::jsonb, 'The child thinks worship can be shared.', 'Offer "Worship the Lord and also other gods" beside "Do not have other gods before the Lord, and do not make idols to bow down to" and ask the child to choose.', 'Read Exodus 20:3-5 and ask what Elijah said to the people in 1 Kings 18:21.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.MOUNT_CARMEL_CONTEST.CARMEL.M_C5_CAR_NO_WATER', 'CRES.G5.THE_BI.MOUNT_CARMEL_CONTEST.CARMEL', 'Thinks Elijah kept the altar dry so it would burn easily.', '{"question":"What did Elijah have poured on the altar before he prayed (1 Kings 18:33-35)?","wrong_answer":"Nothing, he kept it dry","correct_answer":"Water, three times, until the trench was full"}'::jsonb, 'The child reasons that fire needs dry wood.', 'Offer "Nothing, he kept it dry" beside "Water, three times, until the trench was full" and ask the child to choose.', 'Read verses 33-35 and ask why Elijah made it harder: so all would see that only God could do it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.MOUNT_CARMEL_CONTEST.TRUE_GOD.M_C5_TG_LUCK_CHARMS', 'CRES.G5.THE_BI.MOUNT_CARMEL_CONTEST.TRUE_GOD', 'Thinks a lucky charm or object can protect a Christian as God does.', '{"question":"Achieng is given a charm \"for protection\" before an exam. What does the Bible teach?","wrong_answer":"The charm will protect her","correct_answer":"Only God protects; do not trust in objects"}'::jsonb, 'Charms are spoken of at home or in films as having power.', 'Offer "The charm will protect her" beside "Only God protects; do not trust in objects" and ask the child to choose.', 'Link with the idol misconception: an object cannot hear or act. Read Psalm 121:2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.THE_BIRTH_OF_MOSES.MOSES_BIRTH.M_MB_WHO_FOUND', 'CRES.G5.THE_BI.THE_BIRTH_OF_MOSES.MOSES_BIRTH', 'Thinks that the baby was found by someone other than Pharaoh''s daughter.', '{"question":"Who found baby Moses in the basket?","wrong_answer":"His sister","correct_answer":"Pharaoh''s daughter"}'::jsonb, 'The child mixes who watched and who found.', 'Offer "His sister" beside "Pharaoh''s daughter" and ask the child to choose.', 'Read Exodus 2:5-6.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.THE_BIRTH_OF_MOSES.MOSES_BIRTH.M_MB_PLACE', 'CRES.G5.THE_BI.THE_BIRTH_OF_MOSES.MOSES_BIRTH', 'Puts the basket in the Red Sea, mixing Moses'' birth with the crossing of the sea, instead of among the reeds of the Nile.', '{"question":"Where did Moses'' mother put the basket?","wrong_answer":"In the Red Sea","correct_answer":"Among the reeds on the bank of the Nile"}'::jsonb, 'The child mixes Moses'' birth with the crossing of the Red Sea.', 'Offer "In the Red Sea" beside "Among the reeds on the bank of the Nile" and ask the child to choose.', 'Read Exodus 2:3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.THE_BIRTH_OF_MOSES.MOSES_BIRTH.M_MB_NURSE', 'CRES.G5.THE_BI.THE_BIRTH_OF_MOSES.MOSES_BIRTH', 'Thinks Pharaoh''s daughter raised Moses from the first day.', '{"question":"Who nursed baby Moses at first?","wrong_answer":"Pharaoh''s daughter","correct_answer":"His own mother, paid by Pharaoh''s daughter"}'::jsonb, 'The child skips verses 7-9.', 'Offer "Pharaoh''s daughter" beside "His own mother, paid by Pharaoh''s daughter" and ask the child to choose.', 'Read Exodus 2:7-9.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.THE_BIRTH_OF_MOSES.MOSES_BIRTH.M_C5_MB_WHY_HIDE', 'CRES.G5.THE_BI.THE_BIRTH_OF_MOSES.MOSES_BIRTH', 'Does not link the hiding of baby Moses with Pharaoh''s order to kill Hebrew boys, and thinks the mother wanted to get rid of him.', '{"question":"Why did Moses'' mother hide him and then put him in a basket (Exodus 1:22-2:3)?","wrong_answer":"She did not want him","correct_answer":"Pharaoh had ordered every Hebrew baby boy to be thrown into the Nile"}'::jsonb, 'The child sees only the basket and not the danger before it.', 'Offer "She did not want him" beside "Pharaoh had ordered every Hebrew baby boy to be thrown into the Nile" and ask the child to choose.', 'Read Exodus 1:22 first, then 2:2-3. Ask what the mother was saving him from.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.THE_CALL_OF_MOSES.MOSES_CALL.M_MC_BUSH_BURNT', 'CRES.G5.THE_BI.THE_CALL_OF_MOSES.MOSES_CALL', 'Thinks the bush burned up.', '{"question":"What was strange about the bush Moses saw?","wrong_answer":"It burned up quickly","correct_answer":"It burned with fire but was not burned up"}'::jsonb, 'The child expects fire to destroy.', 'Offer "It burned up quickly" beside "It burned with fire but was not burned up" and ask the child to choose.', 'Read Exodus 3:2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.THE_CALL_OF_MOSES.MOSES_CALL.M_MC_SANDALS', 'CRES.G5.THE_BI.THE_CALL_OF_MOSES.MOSES_CALL', 'Says Moses took off his sandals because they were dirty, not because the ground was holy.', '{"question":"Why did God tell Moses to take off his sandals?","wrong_answer":"They were dirty","correct_answer":"The ground where he stood was holy"}'::jsonb, 'The child sees a custom, not reverence.', 'Offer "They were dirty" beside "The ground where he stood was holy" and ask the child to choose.', 'Read Exodus 3:5.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.THE_CALL_OF_MOSES.MOSES_CALL.M_MC_TASK', 'CRES.G5.THE_BI.THE_CALL_OF_MOSES.MOSES_CALL', 'Says God sent Moses to build a temple, mixing Moses with Solomon, instead of going to Pharaoh to bring Israel out of Egypt.', '{"question":"What did God send Moses to do?","wrong_answer":"To build a temple","correct_answer":"To go to Pharaoh and bring the Israelites out of Egypt"}'::jsonb, 'The child mixes Moses with other leaders.', 'Offer "To build a temple" beside "To go to Pharaoh and bring the Israelites out of Egypt" and ask the child to choose.', 'Read Exodus 3:10.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_BI.THE_CALL_OF_MOSES.MOSES_CALL.M_C5_MC_READY', 'CRES.G5.THE_BI.THE_CALL_OF_MOSES.MOSES_CALL', 'Thinks Moses agreed at once and gladly.', '{"question":"How did Moses feel when God spoke from the bush (Exodus 3:6)?","wrong_answer":"Happy and ready at once","correct_answer":"Afraid: he hid his face"}'::jsonb, 'The child expects a hero to be eager.', 'Offer "Happy and ready at once" beside "Afraid: he hid his face" and ask the child to choose.', 'Read Exodus 3:6 and 3:11: Moses hid his face and asked "Who am I?". God promised to be with him.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.JOHN_THE_BAPTIST.JOHN_BAPTIST.M_JB_REPENT_SORRY', 'CRES.G5.THE_LI.JOHN_THE_BAPTIST.JOHN_BAPTIST', 'Thinks repentance is only saying sorry.', '{"question":"What did John the Baptist mean by repentance?","wrong_answer":"Only saying sorry in words","correct_answer":"Turning away from wrong and living a changed life"}'::jsonb, 'The child hears repent and thinks of an apology.', 'Offer "Only saying sorry in words" beside "Turning away from wrong and living a changed life" and ask the child to choose.', 'Read Luke 3:8, "bear fruits that befit repentance".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.JOHN_THE_BAPTIST.JOHN_BAPTIST.M_JB_TAX', 'CRES.G5.THE_LI.JOHN_THE_BAPTIST.JOHN_BAPTIST', 'Thinks John told tax collectors to stop their work or collect more.', '{"question":"What did John tell the tax collectors?","wrong_answer":"Collect more than you are ordered to","correct_answer":"Collect no more than you are ordered to"}'::jsonb, 'The child confuses honest and dishonest collection.', 'Offer "Collect more than you are ordered to" beside "Collect no more than you are ordered to" and ask the child to choose.', 'Read Luke 3:12-13.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.JOHN_THE_BAPTIST.JOHN_BAPTIST.M_JB_SHARE', 'CRES.G5.THE_LI.JOHN_THE_BAPTIST.JOHN_BAPTIST', 'Thinks John told the crowd to keep what they had.', '{"question":"What did John tell people who had two coats?","wrong_answer":"Keep both coats safe","correct_answer":"Share one with someone who has none"}'::jsonb, 'The child focuses on owning.', 'Offer "Keep both coats safe" beside "Share one with someone who has none" and ask the child to choose.', 'Read Luke 3:11.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.JOHN_THE_BAPTIST.JOHN_BAPTIST.M_C5_JB_SOLDIERS', 'CRES.G5.THE_LI.JOHN_THE_BAPTIST.JOHN_BAPTIST', 'Thinks John told soldiers to leave the army.', '{"question":"What did John tell the soldiers (Luke 3:14)?","wrong_answer":"Leave the army","correct_answer":"Do not take money by force or accuse falsely; be content with your pay"}'::jsonb, 'The child expects a preacher to call everyone out of a job that uses force.', 'Offer "Leave the army" beside "Do not take money by force or accuse falsely; be content with your pay" and ask the child to choose.', 'Make a chart: crowd, tax collectors, soldiers, and what John told each. None was told to leave.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.THE_BAPTISM_OF_JESUS_CHR.BAPTISM_JESUS.M_BJ_SIGN', 'CRES.G5.THE_LI.THE_BAPTISM_OF_JESUS_CHR.BAPTISM_JESUS', 'Thinks the dove was an ordinary bird rather than a sign of the Holy Spirit.', '{"question":"What came down on Jesus in the form of a dove?","wrong_answer":"A real dove from the river","correct_answer":"The Holy Spirit"}'::jsonb, 'The child hears dove and pictures a bird.', 'Offer "A real dove from the river" beside "The Holy Spirit" and ask the child to choose.', 'Read Luke 3:22: "in bodily form like a dove".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.THE_BAPTISM_OF_JESUS_CHR.BAPTISM_JESUS.M_BJ_VOICE', 'CRES.G5.THE_LI.THE_BAPTISM_OF_JESUS_CHR.BAPTISM_JESUS', 'Thinks the voice from heaven told Jesus to repent, instead of calling him the beloved Son.', '{"question":"What did the voice from heaven say to Jesus?","wrong_answer":"\"You must repent\"","correct_answer":"\"You are my beloved Son; with you I am well pleased\""}'::jsonb, 'The child mixes this with John''s preaching.', 'Offer ""You must repent"" beside ""You are my beloved Son; with you I am well pleased"" and ask the child to choose.', 'Read Luke 3:22.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.THE_BAPTISM_OF_JESUS_CHR.BAPTISM_JESUS.M_BJ_SINNED', 'CRES.G5.THE_LI.THE_BAPTISM_OF_JESUS_CHR.BAPTISM_JESUS', 'Thinks Jesus was baptised because he had sins to confess.', '{"question":"Why was Jesus baptised?","wrong_answer":"Because he had sins to confess","correct_answer":"To obey God and stand with the people he came to save"}'::jsonb, 'The child links baptism with confession of sin only.', 'Offer "Because he had sins to confess" beside "To obey God and stand with the people he came to save" and ask the child to choose.', 'Ask what the voice said about Jesus right after.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.THE_BAPTISM_OF_JESUS_CHR.BAPTISM_JESUS.M_C5_BJ_WHO_BAPTISED', 'CRES.G5.THE_LI.THE_BAPTISM_OF_JESUS_CHR.BAPTISM_JESUS', 'Thinks Peter or a priest baptised Jesus.', '{"question":"Who baptised Jesus?","wrong_answer":"Peter","correct_answer":"John the Baptist"}'::jsonb, 'Peter is the disciple the child knows best.', 'Offer "Peter" beside "John the Baptist" and ask the child to choose.', 'Read Luke 3:21 with Matthew 3:13: Jesus came to John at the Jordan.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.CALMING_THE_STORM.CALMING_STORM.M_CS_DISCIPLES_CALMED', 'CRES.G5.THE_LI.CALMING_THE_STORM.CALMING_STORM', 'Thinks the disciples stopped the storm.', '{"question":"Who calmed the storm?","wrong_answer":"The disciples rowing hard","correct_answer":"Jesus, by speaking to the wind and the waves"}'::jsonb, 'The child sees the boat crew working.', 'Offer "The disciples rowing hard" beside "Jesus, by speaking to the wind and the waves" and ask the child to choose.', 'Read Mark 4:39.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.CALMING_THE_STORM.CALMING_STORM.M_CS_AWAKE', 'CRES.G5.THE_LI.CALMING_THE_STORM.CALMING_STORM', 'Thinks Jesus was awake and watching the storm.', '{"question":"What was Jesus doing when the storm began?","wrong_answer":"Steering the boat","correct_answer":"Sleeping on a cushion at the back of the boat"}'::jsonb, 'The child expects the leader to be in charge.', 'Offer "Steering the boat" beside "Sleeping on a cushion at the back of the boat" and ask the child to choose.', 'Read Mark 4:38.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.CALMING_THE_STORM.CALMING_STORM.M_CS_NO_TROUBLE', 'CRES.G5.THE_LI.CALMING_THE_STORM.CALMING_STORM', 'Thinks Christians will not face trouble.', '{"question":"What can a Christian learn from the calming of the storm?","wrong_answer":"Christians never face troubles","correct_answer":"Jesus is with us in troubles and has power over them"}'::jsonb, 'The child expects faith to remove all trouble.', 'Offer "Christians never face troubles" beside "Jesus is with us in troubles and has power over them" and ask the child to choose.', 'Ask: were the disciples in the storm with Jesus in the boat?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.CALMING_THE_STORM.CALMING_STORM.M_C5_CS_SCOLDED_STORM_ONLY', 'CRES.G5.THE_LI.CALMING_THE_STORM.CALMING_STORM', 'Thinks Jesus spoke only to the storm and said nothing to the disciples.', '{"question":"What did Jesus ask the disciples after the storm (Mark 4:40)?","wrong_answer":"Nothing","correct_answer":"\"Why are you so afraid? Do you still have no faith?\""}'::jsonb, 'The miracle is remembered and the question after it is lost.', 'Offer "Nothing" beside ""Why are you so afraid? Do you still have no faith?"" and ask the child to choose.', 'Read Mark 4:39-40 and stop after each verse: first the wind, then the disciples.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.FEEDING_THE_FOUR_THOUSAN.FEEDING_4000.M_F4_FIVE_THOUSAND', 'CRES.G5.THE_LI.FEEDING_THE_FOUR_THOUSAN.FEEDING_4000', 'Mixes the feeding of four thousand with five thousand.', '{"question":"How many loaves did Jesus have when he fed the four thousand?","wrong_answer":"Five loaves","correct_answer":"Seven loaves"}'::jsonb, 'Both miracles involve loaves and fish.', 'Offer "Five loaves" beside "Seven loaves" and ask the child to choose.', 'Make a two-column chart: four thousand and five thousand; fill loaves, fish, baskets.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.FEEDING_THE_FOUR_THOUSAN.FEEDING_4000.M_F4_WHY', 'CRES.G5.THE_LI.FEEDING_THE_FOUR_THOUSAN.FEEDING_4000', 'Thinks Jesus fed the people to show off or to make them follow him.', '{"question":"Why did Jesus feed the crowd?","wrong_answer":"To impress them","correct_answer":"Because he had compassion and they had nothing to eat"}'::jsonb, 'The child reads miracles as displays.', 'Offer "To impress them" beside "Because he had compassion and they had nothing to eat" and ask the child to choose.', 'Read Matthew 15:32.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.FEEDING_THE_FOUR_THOUSAN.FEEDING_4000.M_F4_NEEDY_MONEY', 'CRES.G5.THE_LI.FEEDING_THE_FOUR_THOUSAN.FEEDING_4000', 'Thinks helping the needy means only giving money.', '{"question":"Which is a way of helping the needy?","wrong_answer":"Giving only money and nothing else","correct_answer":"Sharing food, clothes or time"}'::jsonb, 'The child links help with money.', 'Offer "Giving only money and nothing else" beside "Sharing food, clothes or time" and ask the child to choose.', 'List five ways with the class: food, clothes, school items, time, prayer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.FEEDING_THE_FOUR_THOUSAN.FEEDING_4000.M_C5_F4_BASKETS', 'CRES.G5.THE_LI.FEEDING_THE_FOUR_THOUSAN.FEEDING_4000', 'Says twelve baskets were left over, the number from the five thousand.', '{"question":"How many basketfuls were left over after the four thousand ate (Matthew 15:37)?","wrong_answer":"Twelve","correct_answer":"Seven"}'::jsonb, 'The two feedings share many details and the numbers swap.', 'Offer "Twelve" beside "Seven" and ask the child to choose.', 'Make a two-column chart: 5,000 (five loaves, twelve baskets) and 4,000 (seven loaves, seven baskets).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.HEALING_THE_PARALYSED_MA.PARALYSED_MAN.M_PM_DOOR', 'CRES.G5.THE_LI.HEALING_THE_PARALYSED_MA.PARALYSED_MAN', 'Thinks the friends carried the man in through the door.', '{"question":"How did the friends get the man to Jesus?","wrong_answer":"Through the open door","correct_answer":"By making an opening in the roof"}'::jsonb, 'The child forgets that the crowd blocked the door.', 'Offer "Through the open door" beside "By making an opening in the roof" and ask the child to choose.', 'Read Mark 2:4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.HEALING_THE_PARALYSED_MA.PARALYSED_MAN.M_PM_HEALED_FIRST', 'CRES.G5.THE_LI.HEALING_THE_PARALYSED_MA.PARALYSED_MAN', 'Thinks Jesus first healed the man''s body.', '{"question":"What did Jesus say first to the paralysed man?","wrong_answer":"\"Rise, take up your mat and walk\"","correct_answer":"\"Son, your sins are forgiven\""}'::jsonb, 'The child expects healing first.', 'Offer ""Rise, take up your mat and walk"" beside ""Son, your sins are forgiven"" and ask the child to choose.', 'Read Mark 2:5.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.HEALING_THE_PARALYSED_MA.PARALYSED_MAN.M_PM_ALONE', 'CRES.G5.THE_LI.HEALING_THE_PARALYSED_MA.PARALYSED_MAN', 'Thinks the man came to Jesus alone.', '{"question":"Whose faith did Jesus see?","wrong_answer":"Only the man''s faith","correct_answer":"The faith of the man and his four friends"}'::jsonb, 'The child hears the story as about one man.', 'Offer "Only the man''s faith" beside "The faith of the man and his four friends" and ask the child to choose.', 'Read Mark 2:3-5: "when Jesus saw their faith".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.HEALING_THE_PARALYSED_MA.PARALYSED_MAN.M_C5_PM_TEACHERS_GLAD', 'CRES.G5.THE_LI.HEALING_THE_PARALYSED_MA.PARALYSED_MAN', 'Thinks the teachers of the law were glad when Jesus forgave the man''s sins.', '{"question":"What did some teachers of the law think when Jesus said \"your sins are forgiven\" (Mark 2:6-7)?","wrong_answer":"They were glad and praised him","correct_answer":"They thought he was blaspheming, because only God forgives sins"}'::jsonb, 'The child expects religious teachers to agree with Jesus.', 'Offer "They were glad and praised him" beside "They thought he was blaspheming, because only God forgives sins" and ask the child to choose.', 'Read Mark 2:6-7 and ask: what did they say only God can do? Jesus then healed the man to show his authority.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.PARABLE_OF_THE_LOST_SHEE.LOST_SHEEP.M_LS_NINETY_NINE', 'CRES.G5.THE_LI.PARABLE_OF_THE_LOST_SHEE.LOST_SHEEP', 'Thinks the shepherd was careless with the ninety-nine, or gave up on the one.', '{"question":"What did the shepherd do when one sheep was lost?","wrong_answer":"He said one sheep was not worth looking for","correct_answer":"He left the ninety-nine and went to look for the lost one"}'::jsonb, 'The child thinks of numbers and not value.', 'Offer "He said one sheep was not worth looking for" beside "He left the ninety-nine and went to look for the lost one" and ask the child to choose.', 'Read Luke 15:4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.PARABLE_OF_THE_LOST_SHEE.LOST_SHEEP.M_LS_PUNISH', 'CRES.G5.THE_LI.PARABLE_OF_THE_LOST_SHEE.LOST_SHEEP', 'Thinks the shepherd punished the sheep when he found it.', '{"question":"How did the shepherd bring the sheep home?","wrong_answer":"He beat it for wandering","correct_answer":"He carried it on his shoulders, rejoicing"}'::jsonb, 'The child expects punishment.', 'Offer "He beat it for wandering" beside "He carried it on his shoulders, rejoicing" and ask the child to choose.', 'Read Luke 15:5.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.PARABLE_OF_THE_LOST_SHEE.LOST_SHEEP.M_LS_JOY', 'CRES.G5.THE_LI.PARABLE_OF_THE_LOST_SHEE.LOST_SHEEP', 'Thinks God is more pleased with those who never go wrong than with one who repents.', '{"question":"What did Jesus say in Luke 15:7?","wrong_answer":"There is no joy in heaven over a sinner","correct_answer":"There is joy in heaven over one sinner who repents"}'::jsonb, 'The child thinks only about the ninety-nine.', 'Offer "There is no joy in heaven over a sinner" beside "There is joy in heaven over one sinner who repents" and ask the child to choose.', 'Read Luke 15:7.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.PARABLE_OF_THE_LOST_SHEE.LOST_SHEEP.M_C5_LS_WHO_TOLD', 'CRES.G5.THE_LI.PARABLE_OF_THE_LOST_SHEE.LOST_SHEEP', 'Forgets why Jesus told the parable: the Pharisees grumbled that he ate with sinners.', '{"question":"Why did Jesus tell the parable of the lost sheep (Luke 15:1-2)?","wrong_answer":"To teach farmers how to keep sheep","correct_answer":"Because Pharisees grumbled that he welcomed sinners"}'::jsonb, 'The child starts the story at the sheep and skips verses 1-2.', 'Offer "To teach farmers how to keep sheep" beside "Because Pharisees grumbled that he welcomed sinners" and ask the child to choose.', 'Read Luke 15:1-2 first and ask: who is the lost sheep in real life?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.SERMON_ON_THE_MOUNT.SERMON_MOUNT.M_SM_PEACE_NO_FIGHT', 'CRES.G5.THE_LI.SERMON_ON_THE_MOUNT.SERMON_MOUNT', 'Thinks a peacemaker is someone who never argues.', '{"question":"What does a peacemaker do when two friends quarrel?","wrong_answer":"Takes the side of the stronger friend","correct_answer":"Helps them to talk and make up"}'::jsonb, 'The child sees peace as silence.', 'Offer "Takes the side of the stronger friend" beside "Helps them to talk and make up" and ask the child to choose.', 'Ask what Matthew 5:9 says peacemakers will be called.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.SERMON_ON_THE_MOUNT.SERMON_MOUNT.M_SM_PURE_CLEAN', 'CRES.G5.THE_LI.SERMON_ON_THE_MOUNT.SERMON_MOUNT', 'Thinks a pure heart means a clean body or clean clothes.', '{"question":"What is a pure heart?","wrong_answer":"A clean body and neat clothes","correct_answer":"A heart that is honest and loves God, without pretending"}'::jsonb, 'The child thinks pure means clean.', 'Offer "A clean body and neat clothes" beside "A heart that is honest and loves God, without pretending" and ask the child to choose.', 'Read Matthew 5:8: "see God".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.SERMON_ON_THE_MOUNT.SERMON_MOUNT.M_SM_MERCY_WEAK', 'CRES.G5.THE_LI.SERMON_ON_THE_MOUNT.SERMON_MOUNT', 'Thinks mercy means being weak.', '{"question":"What does it mean to be merciful?","wrong_answer":"To be weak and let everyone win","correct_answer":"To show kindness and forgive when you have the power to punish"}'::jsonb, 'The child associates mercy with being a pushover.', 'Offer "To be weak and let everyone win" beside "To show kindness and forgive when you have the power to punish" and ask the child to choose.', 'Give the example of a prefect who forgives a first mistake.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.SERMON_ON_THE_MOUNT.SERMON_MOUNT.M_C5_SM_REWARD_MIX', 'CRES.G5.THE_LI.SERMON_ON_THE_MOUNT.SERMON_MOUNT', 'Mixes up the promises: says the peacemakers will see God and the pure in heart will be called children of God.', '{"question":"What does Matthew 5:9 promise the peacemakers?","wrong_answer":"They will see God","correct_answer":"They will be called children of God"}'::jsonb, 'Three blessings and three promises are learnt at once.', 'Offer "They will see God" beside "They will be called children of God" and ask the child to choose.', 'Match three cards to three promises: merciful, mercy; pure in heart, see God; peacemakers, children of God.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.THE_RICH_YOUNG_MAN.RICH_YOUNG_MAN.M_RY_SOLD', 'CRES.G5.THE_LI.THE_RICH_YOUNG_MAN.RICH_YOUNG_MAN', 'Thinks the young man sold everything and followed Jesus.', '{"question":"What did the young man do when Jesus told him to sell his things?","wrong_answer":"He sold everything and followed Jesus","correct_answer":"He went away sad because he had great wealth"}'::jsonb, 'The child expects the story to end well.', 'Offer "He sold everything and followed Jesus" beside "He went away sad because he had great wealth" and ask the child to choose.', 'Read Matthew 19:22.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.THE_RICH_YOUNG_MAN.RICH_YOUNG_MAN.M_RY_RICH_SIN', 'CRES.G5.THE_LI.THE_RICH_YOUNG_MAN.RICH_YOUNG_MAN', 'Thinks Jesus said that being rich is a sin.', '{"question":"What was Jesus showing the young man?","wrong_answer":"That it is wrong to own anything","correct_answer":"That his wealth was holding his heart and he needed to put God first"}'::jsonb, 'The child hears sell and thinks wealth is the wrong.', 'Offer "That it is wrong to own anything" beside "That his wealth was holding his heart and he needed to put God first" and ask the child to choose.', 'Ask whether Jesus told everyone to sell everything.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.THE_RICH_YOUNG_MAN.RICH_YOUNG_MAN.M_RY_OLD', 'CRES.G5.THE_LI.THE_RICH_YOUNG_MAN.RICH_YOUNG_MAN', 'Thinks the man in the story was old, or that he asked Jesus for money.', '{"question":"What did the young man ask Jesus?","wrong_answer":"How he could get more money","correct_answer":"What good thing he must do to have eternal life"}'::jsonb, 'The child pictures a rich old man and skips the first question.', 'Offer "How he could get more money" beside "What good thing he must do to have eternal life" and ask the child to choose.', 'Read Matthew 19:16.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.THE_RICH_YOUNG_MAN.RICH_YOUNG_MAN.M_C5_RY_COMMANDMENTS_ENOUGH', 'CRES.G5.THE_LI.THE_RICH_YOUNG_MAN.RICH_YOUNG_MAN', 'Thinks keeping the commandments in words was all the young man needed, so Jesus asked nothing more.', '{"question":"The young man said he had kept the commandments. What did Jesus then ask of him (Matthew 19:21)?","wrong_answer":"Nothing more","correct_answer":"To sell his possessions, give to the poor, and follow him"}'::jsonb, 'The child stops reading when the man says he kept the rules.', 'Offer "Nothing more" beside "To sell his possessions, give to the poor, and follow him" and ask the child to choose.', 'Read 19:20-21: "What do I still lack?" Jesus showed him what held his heart.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.A_FRIEND_AT_MIDNIGHT.FRIEND_MIDNIGHT.M_FM_FRIENDSHIP_ONLY', 'CRES.G5.THE_LI.A_FRIEND_AT_MIDNIGHT.FRIEND_MIDNIGHT', 'Thinks the friend got up only because of friendship.', '{"question":"Why did the friend at last get up and give the loaves?","wrong_answer":"Only because of friendship","correct_answer":"Because the man kept asking"}'::jsonb, 'The child gives the first reason that comes to mind.', 'Offer "Only because of friendship" beside "Because the man kept asking" and ask the child to choose.', 'Read Luke 11:8.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.A_FRIEND_AT_MIDNIGHT.FRIEND_MIDNIGHT.M_FM_ONE_PRAYER', 'CRES.G5.THE_LI.A_FRIEND_AT_MIDNIGHT.FRIEND_MIDNIGHT', 'Thinks one prayer is enough and God is annoyed by repeated prayer.', '{"question":"What does the parable teach about prayer?","wrong_answer":"One short prayer is enough and we should not ask again","correct_answer":"We should pray without giving up"}'::jsonb, 'The child thinks repeating is rude.', 'Offer "One short prayer is enough and we should not ask again" beside "We should pray without giving up" and ask the child to choose.', 'Read Luke 11:9-10: ask, seek, knock.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.A_FRIEND_AT_MIDNIGHT.FRIEND_MIDNIGHT.M_FM_LOAVES', 'CRES.G5.THE_LI.A_FRIEND_AT_MIDNIGHT.FRIEND_MIDNIGHT', 'Says the man asked for seven loaves, mixing the parable with the feeding of the four thousand, instead of three.', '{"question":"How many loaves did the man ask for?","wrong_answer":"Seven loaves","correct_answer":"Three loaves"}'::jsonb, 'The child mixes this with the feeding of the four thousand.', 'Offer "Seven loaves" beside "Three loaves" and ask the child to choose.', 'Read Luke 11:5-6.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_LI.A_FRIEND_AT_MIDNIGHT.FRIEND_MIDNIGHT.M_C5_FM_GOD_ASLEEP', 'CRES.G5.THE_LI.A_FRIEND_AT_MIDNIGHT.FRIEND_MIDNIGHT', 'Thinks the parable shows God is like the sleepy friend who does not want to help.', '{"question":"Is God like the friend in bed who did not want to get up?","wrong_answer":"Yes, God is unwilling to help","correct_answer":"No: if even a tired friend gives, God, a loving Father, gives much more"}'::jsonb, 'The child maps every character straight onto God.', 'Offer "Yes, God is unwilling to help" beside "No: if even a tired friend gives, God, a loving Father, gives much more" and ask the child to choose.', 'Read Luke 11:11-13: if earthly fathers give good gifts, how much more God. The lesson is persistence, not that God is unwilling.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_CH.THE_EARLY_CHURCH.EARLY_CHURCH.M_EC_OWN', 'CRES.G5.THE_CH.THE_EARLY_CHURCH.EARLY_CHURCH', 'Thinks the early believers kept their possessions private.', '{"question":"What did the early believers do with what they owned?","wrong_answer":"Kept it for themselves","correct_answer":"Shared it with anyone in need"}'::jsonb, 'The child compares with life today.', 'Offer "Kept it for themselves" beside "Shared it with anyone in need" and ask the child to choose.', 'Read Acts 2:44-45.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_CH.THE_EARLY_CHURCH.EARLY_CHURCH.M_EC_SAME_JOB', 'CRES.G5.THE_CH.THE_EARLY_CHURCH.EARLY_CHURCH', 'Thinks unity means everyone doing the same thing.', '{"question":"What keeps a church united?","wrong_answer":"Everyone doing exactly the same job","correct_answer":"Love, sharing, forgiveness and humility"}'::jsonb, 'The child confuses unity with sameness.', 'Offer "Everyone doing exactly the same job" beside "Love, sharing, forgiveness and humility" and ask the child to choose.', 'List values and ask which can be practised by anyone.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_CH.THE_EARLY_CHURCH.EARLY_CHURCH.M_EC_WHAT_DEVOTED', 'CRES.G5.THE_CH.THE_EARLY_CHURCH.EARLY_CHURCH', 'Picks selling for profit as something the early believers devoted themselves to, instead of the apostles'' teaching, fellowship, breaking bread and prayer.', '{"question":"Which one did the early believers devote themselves to?","wrong_answer":"Selling things for profit","correct_answer":"The apostles'' teaching, fellowship, breaking bread and prayer"}'::jsonb, 'The child skips the list in verse 42.', 'Offer "Selling things for profit" beside "The apostles'' teaching, fellowship, breaking bread and prayer" and ask the child to choose.', 'Read Acts 2:42 and write the four things.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_CH.THE_EARLY_CHURCH.EARLY_CHURCH.M_C5_EC_DAILY_TEMPLE', 'CRES.G5.THE_CH.THE_EARLY_CHURCH.EARLY_CHURCH', 'Thinks the early believers met only once a week and never ate together.', '{"question":"How often did the early believers meet, according to Acts 2:46?","wrong_answer":"Only once a month","correct_answer":"Every day, in the temple courts and in homes, eating together"}'::jsonb, 'The child knows church as a Sunday event.', 'Offer "Only once a month" beside "Every day, in the temple courts and in homes, eating together" and ask the child to choose.', 'Read Acts 2:46 and underline "every day" and "ate together".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_CH.THE_LORD_S_SUPPER.LORDS_SUPPER.M_LS2_ONE_NAME', 'CRES.G5.THE_CH.THE_LORD_S_SUPPER.LORDS_SUPPER', 'Thinks only one name for the Lord''s Supper is correct.', '{"question":"Churches call the Lord''s Supper by different names. Which is true?","wrong_answer":"Only one name is correct and the others are wrong","correct_answer":"Lord''s Supper, Lord''s Table, Holy Communion and Eucharist are names used for the same remembrance"}'::jsonb, 'The child hears one name at home.', 'Offer "Only one name is correct and the others are wrong" beside "Lord''s Supper, Lord''s Table, Holy Communion and Eucharist are names used for the same remembrance" and ask the child to choose.', 'Ask your own church''s name and the names other churches use.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_CH.THE_LORD_S_SUPPER.LORDS_SUPPER.M_LS2_WHEN', 'CRES.G5.THE_CH.THE_LORD_S_SUPPER.LORDS_SUPPER', 'Thinks Jesus shared the Lord''s Supper with a crowd of thousands, mixing it with the feeding miracles, instead of with his apostles.', '{"question":"With whom did Jesus share the Passover meal in Luke 22?","wrong_answer":"With a crowd of five thousand","correct_answer":"With his apostles"}'::jsonb, 'The child mixes this with a feeding miracle.', 'Offer "With a crowd of five thousand" beside "With his apostles" and ask the child to choose.', 'Read Luke 22:14.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_CH.THE_LORD_S_SUPPER.LORDS_SUPPER.M_LS2_WHY', 'CRES.G5.THE_CH.THE_LORD_S_SUPPER.LORDS_SUPPER', 'Thinks the meal is a normal meal or a reward for good behaviour.', '{"question":"What did Jesus say to do with the bread and the cup?","wrong_answer":"Do this as a prize for the best behaved","correct_answer":"Do this in remembrance of me"}'::jsonb, 'The child does not link it to remembering.', 'Offer "Do this as a prize for the best behaved" beside "Do this in remembrance of me" and ask the child to choose.', 'Read Luke 22:19.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_CH.THE_LORD_S_SUPPER.LORDS_SUPPER.M_C5_LS2_FEAST', 'CRES.G5.THE_CH.THE_LORD_S_SUPPER.LORDS_SUPPER', 'Thinks the Lord''s Supper was a wedding feast or a feast for the crowd.', '{"question":"Which meal were Jesus and his apostles eating in Luke 22:15?","wrong_answer":"A wedding feast","correct_answer":"The Passover"}'::jsonb, 'The child knows other meals of Jesus, such as Cana.', 'Offer "A wedding feast" beside "The Passover" and ask the child to choose.', 'Read Luke 22:15 and say: Passover remembered God bringing Israel out of Egypt.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_CH.THE_HOLY_SPIRIT.HOLY_SPIRIT.M_HS_MIX', 'CRES.G5.THE_CH.THE_HOLY_SPIRIT.HOLY_SPIRIT', 'Mixes the gifts and the fruit of the Spirit.', '{"question":"Which one is a fruit of the Holy Spirit?","wrong_answer":"Prophecy","correct_answer":"Kindness"}'::jsonb, 'Both lists have nine items and sound alike.', 'Offer "Prophecy" beside "Kindness" and ask the child to choose.', 'Make two lists, gifts from 1 Corinthians 12 and fruit from Galatians 5.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_CH.THE_HOLY_SPIRIT.HOLY_SPIRIT.M_HS_COUNT', 'CRES.G5.THE_CH.THE_HOLY_SPIRIT.HOLY_SPIRIT', 'Says there are five gifts of the Spirit in 1 Corinthians 12, using a number met earlier, instead of nine.', '{"question":"How many gifts of the Holy Spirit are listed in 1 Corinthians 12:1-11?","wrong_answer":"Five","correct_answer":"Nine"}'::jsonb, 'The child remembers a number but not which.', 'Offer "Five" beside "Nine" and ask the child to choose.', 'Count the gifts in verses 8 to 10 together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_CH.THE_HOLY_SPIRIT.HOLY_SPIRIT.M_HS_HARMONY', 'CRES.G5.THE_CH.THE_HOLY_SPIRIT.HOLY_SPIRIT', 'Thinks patience means leaving quarrels unsolved, instead of bearing with one another so people live in harmony.', '{"question":"How does the fruit of patience help Christians?","wrong_answer":"It makes them leave quarrels unsolved","correct_answer":"It helps them to bear with one another and live in harmony"}'::jsonb, 'The child sees the fruit as private feelings.', 'Offer "It makes them leave quarrels unsolved" beside "It helps them to bear with one another and live in harmony" and ask the child to choose.', 'Ask what a patient friend does when you make a mistake.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_CH.THE_HOLY_SPIRIT.HOLY_SPIRIT.M_C5_HS_GIFTS_FEW', 'CRES.G5.THE_CH.THE_HOLY_SPIRIT.HOLY_SPIRIT', 'Thinks the gifts of the Spirit are only for pastors, not for every believer.', '{"question":"To whom does the Spirit give gifts, according to 1 Corinthians 12:7?","wrong_answer":"Only pastors","correct_answer":"To each believer, for the common good"}'::jsonb, 'The child sees gifts like prophecy used mostly by church leaders.', 'Offer "Only pastors" beside "To each believer, for the common good" and ask the child to choose.', 'Read 1 Corinthians 12:7 and 12:11: to each one, as the Spirit decides.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_CH.PETER_S_MIRACULOUS_RESCU.PETER_RESCUE.M_PR_BROKE_OUT', 'CRES.G5.THE_CH.PETER_S_MIRACULOUS_RESCU.PETER_RESCUE', 'Thinks Peter broke out of prison by his own effort.', '{"question":"How did Peter get out of prison?","wrong_answer":"He broke the chains himself","correct_answer":"An angel woke him and the chains fell off"}'::jsonb, 'The child likes an escape story.', 'Offer "He broke the chains himself" beside "An angel woke him and the chains fell off" and ask the child to choose.', 'Read Acts 12:7.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_CH.PETER_S_MIRACULOUS_RESCU.PETER_RESCUE.M_PR_NO_PRAYER', 'CRES.G5.THE_CH.PETER_S_MIRACULOUS_RESCU.PETER_RESCUE', 'Thinks the church was not praying, or forgot Peter.', '{"question":"What was the church doing while Peter was in prison?","wrong_answer":"Waiting quietly and doing nothing","correct_answer":"Praying earnestly to God for him"}'::jsonb, 'The child focuses on Peter alone.', 'Offer "Waiting quietly and doing nothing" beside "Praying earnestly to God for him" and ask the child to choose.', 'Read Acts 12:5.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_CH.PETER_S_MIRACULOUS_RESCU.PETER_RESCUE.M_PR_RHODA', 'CRES.G5.THE_CH.PETER_S_MIRACULOUS_RESCU.PETER_RESCUE', 'Thinks Rhoda opened the gate at once.', '{"question":"What did Rhoda do when she heard Peter''s voice?","wrong_answer":"Opened the gate immediately","correct_answer":"Ran in with joy and forgot to open it"}'::jsonb, 'The child skips the funny detail.', 'Offer "Opened the gate immediately" beside "Ran in with joy and forgot to open it" and ask the child to choose.', 'Read Acts 12:13-14.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.THE_CH.PETER_S_MIRACULOUS_RESCU.PETER_RESCUE.M_C5_PR_HOUSE', 'CRES.G5.THE_CH.PETER_S_MIRACULOUS_RESCU.PETER_RESCUE', 'Thinks Peter went to the temple or to Herod after his rescue.', '{"question":"Where did Peter go after the angel left him (Acts 12:12)?","wrong_answer":"To Herod''s palace","correct_answer":"To the house of Mary the mother of John Mark, where many were praying"}'::jsonb, 'The child does not connect the rescue with the praying church.', 'Offer "To Herod''s palace" beside "To the house of Mary the mother of John Mark, where many were praying" and ask the child to choose.', 'Read Acts 12:12 and draw the house full of praying people. Peter went where they were praying for him.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CHRIST.FRIENDSHIP_FORMATION.FRIENDS.M_FR_POPULAR', 'CRES.G5.CHRIST.FRIENDSHIP_FORMATION.FRIENDS', 'Chooses friends by popularity or what they own.', '{"question":"Which is the best reason to choose a friend?","wrong_answer":"Because he is popular and has nice things","correct_answer":"Because he is honest, kind and respectful"}'::jsonb, 'The child looks at what others admire.', 'Offer "Because he is popular and has nice things" beside "Because he is honest, kind and respectful" and ask the child to choose.', 'List qualities with the class before naming friends.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CHRIST.FRIENDSHIP_FORMATION.FRIENDS.M_FR_FOLLOW', 'CRES.G5.CHRIST.FRIENDSHIP_FORMATION.FRIENDS', 'Thinks you must do what a friend asks to keep the friendship.', '{"question":"A friend asks you to copy answers in a test. What should you do?","wrong_answer":"Copy so that you keep your friend","correct_answer":"Say no politely and offer to help study instead"}'::jsonb, 'The child fears losing the friend.', 'Offer "Copy so that you keep your friend" beside "Say no politely and offer to help study instead" and ask the child to choose.', 'Practise a short polite refusal in pairs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CHRIST.FRIENDSHIP_FORMATION.FRIENDS.M_FR_PROVERB', 'CRES.G5.CHRIST.FRIENDSHIP_FORMATION.FRIENDS', 'Thinks Proverbs 22:24-25 says to befriend a hot-tempered person, reversing its warning.', '{"question":"What does Proverbs 22:24-25 advise?","wrong_answer":"Be friends with a person who has a quick temper","correct_answer":"Do not make friends with a person who is easily angered"}'::jsonb, 'The child skips the reading.', 'Offer "Be friends with a person who has a quick temper" beside "Do not make friends with a person who is easily angered" and ask the child to choose.', 'Read Proverbs 22:24-25.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CHRIST.FRIENDSHIP_FORMATION.FRIENDS.M_C5_FR_CHANGE_THEM', 'CRES.G5.CHRIST.FRIENDSHIP_FORMATION.FRIENDS', 'Thinks a child should stay close to friends who do wrong in order to change them, even when they pull him in.', '{"question":"Your friends steal from the canteen and want you to join. What is wise?","wrong_answer":"Stay with them so I can change them","correct_answer":"Say no and spend time with friends who do right"}'::jsonb, 'The child wants to keep friends and believes he will be the stronger one.', 'Offer "Stay with them so I can change them" beside "Say no and spend time with friends who do right" and ask the child to choose.', 'Read Proverbs 22:25: you may learn their ways. Practise walking away kindly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CHRIST.HUMAN_SEXUALITY.ADOLESCENCE.M_AD_SHAME', 'CRES.G5.CHRIST.HUMAN_SEXUALITY.ADOLESCENCE', 'Thinks changes of growing up are shameful and must be hidden.', '{"question":"How should a child feel about the changes of adolescence?","wrong_answer":"Ashamed, and tell no one","correct_answer":"They are normal, and I can ask a parent or trusted adult"}'::jsonb, 'The child hears no open talk at home.', 'Offer "Ashamed, and tell no one" beside "They are normal, and I can ask a parent or trusted adult" and ask the child to choose.', 'Say that all adults went through the same changes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CHRIST.HUMAN_SEXUALITY.ADOLESCENCE.M_AD_FRIEND_INFO', 'CRES.G5.CHRIST.HUMAN_SEXUALITY.ADOLESCENCE', 'Trusts friends or the internet as the best source about the body.', '{"question":"Where is the best place to find the right information about growing up?","wrong_answer":"From friends and anything on the internet","correct_answer":"From a parent, guardian, teacher or health worker you trust"}'::jsonb, 'The child asks those the same age.', 'Offer "From friends and anything on the internet" beside "From a parent, guardian, teacher or health worker you trust" and ask the child to choose.', 'Compare a friend''s guess with a nurse''s answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CHRIST.HUMAN_SEXUALITY.ADOLESCENCE.M_AD_SECRET', 'CRES.G5.CHRIST.HUMAN_SEXUALITY.ADOLESCENCE', 'Thinks a secret friendship with an older person is harmless.', '{"question":"Which is a sign of an unhealthy friendship?","wrong_answer":"The friend says to keep it secret and gives gifts for favours","correct_answer":"The friend respects you and your parents know about it"}'::jsonb, 'The child enjoys the attention.', 'Offer "The friend says to keep it secret and gives gifts for favours" beside "The friend respects you and your parents know about it" and ask the child to choose.', 'List warning signs: secrecy, pressure, gifts for favours.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CHRIST.HUMAN_SEXUALITY.ADOLESCENCE.M_AD_BODY', 'CRES.G5.CHRIST.HUMAN_SEXUALITY.ADOLESCENCE', 'Mixes up the changes in boys and girls.', '{"question":"Which change usually happens in girls at adolescence?","wrong_answer":"The voice becomes deep","correct_answer":"Monthly periods begin"}'::jsonb, 'The child has heard fragments from friends.', 'Offer "The voice becomes deep" beside "Monthly periods begin" and ask the child to choose.', 'Use a health-class chart.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CHRIST.SANCTITY_OF_LIFE.SANCTITY_LIFE.M_SL_ANIMALS', 'CRES.G5.CHRIST.SANCTITY_OF_LIFE.SANCTITY_LIFE', 'Thinks sanctity of life means only that we must not kill animals.', '{"question":"What does it mean that human life is sacred?","wrong_answer":"Animals must never be used","correct_answer":"Human life is holy because it comes from God and is made in his image"}'::jsonb, 'The child extends the word sacred.', 'Offer "Animals must never be used" beside "Human life is holy because it comes from God and is made in his image" and ask the child to choose.', 'Read Genesis 1:27 and 9:6.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CHRIST.SANCTITY_OF_LIFE.SANCTITY_LIFE.M_SL_ANGER', 'CRES.G5.CHRIST.SANCTITY_OF_LIFE.SANCTITY_LIFE', 'Thinks that the best way to cope with anger is to hit back.', '{"question":"What is a safe way to cope with anger?","wrong_answer":"Hit back so that the other child learns","correct_answer":"Walk away, breathe, and tell a trusted person"}'::jsonb, 'The child sees revenge as justice.', 'Offer "Hit back so that the other child learns" beside "Walk away, breathe, and tell a trusted person" and ask the child to choose.', 'Role-play walking away.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CHRIST.SANCTITY_OF_LIFE.SANCTITY_LIFE.M_SL_SOURCE', 'CRES.G5.CHRIST.SANCTITY_OF_LIFE.SANCTITY_LIFE', 'Thinks life comes from parents alone or from chance.', '{"question":"According to Christian teaching, who is the source of life?","wrong_answer":"Only a person''s parents","correct_answer":"God, the giver of life"}'::jsonb, 'The child sees parents as the source.', 'Offer "Only a person''s parents" beside "God, the giver of life" and ask the child to choose.', 'Read Genesis 2:7.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CHRIST.SANCTITY_OF_LIFE.SANCTITY_LIFE.M_C5_SL_SOME_LIVES', 'CRES.G5.CHRIST.SANCTITY_OF_LIFE.SANCTITY_LIFE', 'Thinks the lives of the poor, the sick or the disabled matter less.', '{"question":"Whose life is sacred in God''s eyes?","wrong_answer":"Only healthy and rich people","correct_answer":"Every person, because each is made in God''s image"}'::jsonb, 'The child sees how some people are treated and takes it as their worth.', 'Offer "Only healthy and rich people" beside "Every person, because each is made in God''s image" and ask the child to choose.', 'Read Genesis 1:27: every person is made in God''s image. Name people the world may overlook.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS.M_DR_MEDICINE', 'CRES.G5.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS', 'Thinks medicine from a hospital is the same as drug abuse.', '{"question":"Which is drug abuse?","wrong_answer":"Taking medicine as the doctor says","correct_answer":"Sniffing glue to feel different"}'::jsonb, 'The child hears drug and thinks of anything swallowed.', 'Offer "Taking medicine as the doctor says" beside "Sniffing glue to feel different" and ask the child to choose.', 'Ask the difference between medicine given by a nurse and a pill taken for fun.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS.M_DR_ONLY_ADULTS', 'CRES.G5.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS', 'Thinks only adults abuse alcohol and drugs, or that a child cannot be tempted.', '{"question":"Who can be tempted to use drugs?","wrong_answer":"Only adults","correct_answer":"Both adults and children, especially when friends pressure them"}'::jsonb, 'The child sees drug use in adults only.', 'Offer "Only adults" beside "Both adults and children, especially when friends pressure them" and ask the child to choose.', 'Ask about older pupils who offer cigarettes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS.M_DR_SAFE_ONE', 'CRES.G5.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS', 'Thinks trying a drug once will do no harm.', '{"question":"What is true about trying a harmful drug just once?","wrong_answer":"One try can never harm you","correct_answer":"It can start a habit that is hard to break"}'::jsonb, 'The child underestimates addiction.', 'Offer "One try can never harm you" beside "It can start a habit that is hard to break" and ask the child to choose.', 'Say that many people started with one try.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS.M_DR_EFFECT', 'CRES.G5.CHRIST.ALCOHOL_DRUGS_AND_SUBSTA.DRUGS', 'Thinks drugs make a person stronger or better at school.', '{"question":"What is an effect of alcohol and drug abuse?","wrong_answer":"Better health and better marks","correct_answer":"Poor health, failing at school and quarrels"}'::jsonb, 'The child hears claims of strength and relief.', 'Offer "Better health and better marks" beside "Poor health, failing at school and quarrels" and ask the child to choose.', 'Ask about families affected.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CHRIST.SOCIAL_MEDIA.SOCIAL_MEDIA.M_SM2_SHARE_ALL', 'CRES.G5.CHRIST.SOCIAL_MEDIA.SOCIAL_MEDIA', 'Thinks it is safe to share passwords, address and photos with online friends.', '{"question":"Which information must you keep private online?","wrong_answer":"Your favourite colour","correct_answer":"Your password and home address"}'::jsonb, 'The child treats online friends like real friends.', 'Offer "Your favourite colour" beside "Your password and home address" and ask the child to choose.', 'List what a stranger could do with an address.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CHRIST.SOCIAL_MEDIA.SOCIAL_MEDIA.M_SM2_ONLY_GOOD', 'CRES.G5.CHRIST.SOCIAL_MEDIA.SOCIAL_MEDIA', 'Thinks social media has only advantages, or only disadvantages.', '{"question":"What is a disadvantage of social media?","wrong_answer":"It helps you talk to relatives far away","correct_answer":"It can waste time and spread false or harmful messages"}'::jsonb, 'The child hears one side only.', 'Offer "It helps you talk to relatives far away" beside "It can waste time and spread false or harmful messages" and ask the child to choose.', 'Make two lists, advantages and disadvantages.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CHRIST.SOCIAL_MEDIA.SOCIAL_MEDIA.M_SM2_STRANGER', 'CRES.G5.CHRIST.SOCIAL_MEDIA.SOCIAL_MEDIA', 'Thinks a stranger who is kind online can be trusted and met.', '{"question":"A stranger online says he is a child and asks to meet you. What should you do?","wrong_answer":"Meet him, because he is kind","correct_answer":"Do not reply, and tell a parent or teacher"}'::jsonb, 'The child cannot tell who is really online.', 'Offer "Meet him, because he is kind" beside "Do not reply, and tell a parent or teacher" and ask the child to choose.', 'Say that people can lie about who they are.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CRES.G5.CHRIST.SOCIAL_MEDIA.SOCIAL_MEDIA.M_SM2_FORWARD', 'CRES.G5.CHRIST.SOCIAL_MEDIA.SOCIAL_MEDIA', 'Thinks forwarding any message, even if unkind or unproven, is harmless.', '{"question":"You receive an unkind message about a classmate. What should you do?","wrong_answer":"Forward it to the class","correct_answer":"Delete it and not pass it on"}'::jsonb, 'The child sees forwarding as a click.', 'Offer "Forward it to the class" beside "Delete it and not pass it on" and ask the child to choose.', 'Ask how the classmate would feel.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
